/* REBUILD OS · local-first application */
(() => {
  'use strict';

  // 1. Constants
  const KEY = 'rebuildOS_v1';
  const NAV = [
    ['today','Today','⌂'],['protocol','Protocol','◷'],['focus','Focus','◉'],
    ['journal','Journal','≡'],['analytics','Analytics','▥'],['settings','Settings','⚙']
  ];
  const PRAYERS = ['Fajr','Dhuhr','Asr','Maghrib','Isha'];
  const PHASES = [
    {name:'Reset',from:1,to:3,focus:'Regain control, fix sleep, establish prayer, protect mornings, choose one project.'},
    {name:'Finish',from:4,to:7,focus:'Ship features, close tasks, stay with one project, deploy something usable.'},
    {name:'Understand',from:8,to:10,focus:'Strengthen JavaScript, APIs, data, security, and your understanding of the code.'},
    {name:'Ship',from:11,to:13,focus:'Polish mobile, handle errors and empty states, deploy, and share the work.'},
    {name:'Proof Day',from:14,to:14,focus:'Review, deploy, document, reflect, and decide the next cycle.'}
  ];
  const DAY_THEMES = [
    'Reset the environment','Protect the first hours','Choose one project','Ship the first feature',
    'Close an open loop','Build the core flow','Make it usable','Understand the foundations',
    'Trace the data','Explain the system','Polish the experience','Handle the edge cases',
    'Deploy and share','Review the proof'
  ];
  const DEFAULT_ROUTINE = [
    ['Fajr','05:30','05:50','prayer'],['Wake up','07:00','07:10','routine'],
    ['Morning routine','07:10','07:40','routine'],['Coding Block 1','08:00','10:00','coding'],
    ['Dhuhr','13:00','13:15','prayer'],['Math','14:00','15:00','math'],
    ['Asr','16:30','16:45','prayer'],['Exercise / walk','17:00','17:45','body'],
    ['Coding Block 2','19:00','20:00','coding'],['Maghrib','19:30','19:45','prayer'],
    ['Isha','21:00','21:15','prayer'],['Review and shutdown','21:30','22:00','routine'],
    ['Livestream','22:00','01:00','stream'],['Sleep','23:30','07:00','sleep']
  ];
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
  const localDate = (date=new Date()) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
  const parseDate = value => { const [y,m,d]=String(value||'').split('-').map(Number); return new Date(y||2000,(m||1)-1,d||1,12); };
  const addDays = (date,n) => { const d=parseDate(date); d.setDate(d.getDate()+n); return localDate(d); };
  const dayDiff = (a,b) => Math.round((parseDate(b)-parseDate(a))/86400000);
  const fmtDate = (date, opts={weekday:'long',month:'long',day:'numeric'}) => parseDate(date).toLocaleDateString(undefined,opts);
  const fmtTime = time => { if(!time)return 'Not set'; const [h,m]=time.split(':').map(Number); return new Date(2000,0,1,h||0,m||0).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}); };
  const mins = n => { n=Math.max(0,Math.floor(Number(n)||0)); return `${Math.floor(n/60)}h ${String(n%60).padStart(2,'0')}m`; };
  const durationLabel = seconds => `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
  const todayISO = () => localDate();
  const blankRecord = date => ({date,prayers:{},prayerCompletedAt:{},coding:{minutes:0,mission:'',tasks:[],notes:''},math:{minutes:0,questions:0,correct:0,incorrect:0,topic:'',notes:''},exercise:{workout:false,walking:0,workoutMinutes:0,steps:'',type:'Walking',notes:''},dopamine:{protected:false,gaming:false,anime:false,scrolling:false},sleep:{bedtime:'',wakeTime:'',duration:0},stream:{watched:false,start:'22:00',end:'01:00',learned:'',useful:'',tomorrow:''},journal:{morningMission:'',mustHappen:'',avoid:'',completed:'',distracted:'',learned:'',improve:'',mood:3,energy:3,stress:3},routine:{},shutdown:{},lockIn:{mission:'',topic:'',workout:'',distraction:'',locked:false},score:0,rescueMode:false,rescue:{prayer:false,coding:false,math:false,walk:false},closedDay:false,tomorrowMission:'',timeline:[]});
  const defaultState = () => ({version:1,profile:{name:'',startDate:todayISO(),wakeTime:'07:00',sleepTime:'23:30',sleepTarget:7.5,projectName:'',projectSummary:'',features:['','',''],doneDefinition:'',examName:'',examDate:'',exerciseType:'Walking',prayerTimes:{Fajr:'05:30',Dhuhr:'13:00',Asr:'16:30',Maghrib:'19:30',Isha:'21:00'},streamStart:'22:00',streamEnd:'01:00'},settings:{codingTarget:180,mathTarget:60,exerciseTarget:30,theme:'dark',accent:'green',notifications:true,reducedMotion:false,timeline:true},currentCycleId:'',cycles:[],projects:[],dailyRecords:{},focusSessions:[],achievements:[],appState:{page:'today',focusMode:false,timer:null,setupComplete:false}});

  // 2. State and storage
  let state;
  try { const raw=localStorage.getItem(KEY); state=raw?JSON.parse(raw):defaultState(); if(!state||typeof state!=='object'||state.version!==1) state=defaultState(); }
  catch { state=defaultState(); }
  const ensureShape = () => {
    const base=defaultState();
    for(const key of ['profile','settings','appState']) state[key]={...base[key],...(state[key]||{})};
    state.profile.prayerTimes={...base.profile.prayerTimes,...(state.profile.prayerTimes||{})};
    state.dailyRecords=state.dailyRecords&&typeof state.dailyRecords==='object'?state.dailyRecords:{};
    state.focusSessions=Array.isArray(state.focusSessions)?state.focusSessions:[];
    state.cycles=Array.isArray(state.cycles)?state.cycles:[];
    state.achievements=Array.isArray(state.achievements)?state.achievements:[];
    state.profile.topics=Array.isArray(state.profile.topics)?state.profile.topics:[];
    state.profile.features=Array.isArray(state.profile.features)?state.profile.features:['','',''];
    state.dailyRecords=Object.fromEntries(Object.entries(state.dailyRecords).filter(([date,value])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&value&&typeof value==='object'&&!Array.isArray(value)));
    state.profile.topics=state.profile.topics.filter(t=>t&&typeof t==='object'&&!Array.isArray(t)).map(t=>({id:String(t.id||uid()),name:String(t.name||'Untitled topic').slice(0,120),notes:String(t.notes||''),done:!!t.done,confidence:Math.min(5,Math.max(1,Number(t.confidence)||1)),questions:Math.max(0,Number(t.questions)||0),correct:Math.max(0,Number(t.correct)||0),incorrect:Math.max(0,Number(t.incorrect)||0),minutes:Math.max(0,Number(t.minutes)||0),lastStudied:String(t.lastStudied||'')}));
    state.profile.features=state.profile.features.slice(0,3).map(f=>f&&typeof f==='object'?{text:String(f.text||'').slice(0,180),done:!!f.done}:{text:String(f||'').slice(0,180),done:false});while(state.profile.features.length<3)state.profile.features.push({text:'',done:false});
    state.cycles=state.cycles.filter(c=>c&&typeof c==='object'&&typeof c.startDate==='string').map(c=>({id:String(c.id||uid()),startDate:c.startDate,label:String(c.label||'14-Day Rebuild Protocol'),createdAt:String(c.createdAt||'')}));
    state.focusSessions=state.focusSessions.filter(s=>s&&typeof s==='object'&&!Array.isArray(s)).map(s=>({...s,id:String(s.id||uid()),date:/^\d{4}-\d{2}-\d{2}$/.test(s.date)?s.date:todayISO(),type:['Coding','Math','Workout','Custom'].includes(s.type)?s.type:'Custom',minutes:Math.max(0,Number(s.minutes)||0),task:String(s.task||''),notes:String(s.notes||'')}));
    state.settings.codingTarget=Math.max(1,Number(state.settings.codingTarget)||180);state.settings.mathTarget=Math.max(1,Number(state.settings.mathTarget)||60);state.settings.exerciseTarget=Math.max(1,Number(state.settings.exerciseTarget)||30);
    for(const date of Object.keys(state.dailyRecords)){const r=record(date);r.prayers=Object.fromEntries(PRAYERS.map(p=>[p,!!r.prayers[p]]));r.prayerCompletedAt=r.prayerCompletedAt&&typeof r.prayerCompletedAt==='object'?r.prayerCompletedAt:{};r.coding.tasks=Array.isArray(r.coding.tasks)?r.coding.tasks.filter(t=>t&&typeof t==='object').map(t=>({id:String(t.id||uid()),text:String(t.text||'').slice(0,180),done:!!t.done,createdAt:String(t.createdAt||''),completedAt:String(t.completedAt||'')})):[];r.coding.minutes=Math.max(0,Number(r.coding.minutes)||0);r.math.minutes=Math.max(0,Number(r.math.minutes)||0);r.math.questions=Math.max(0,Number(r.math.questions)||0);r.math.correct=Math.max(0,Number(r.math.correct)||0);r.math.incorrect=Math.max(0,Number(r.math.incorrect)||0);r.exercise.walking=Math.max(0,Number(r.exercise.walking)||0);r.exercise.workoutMinutes=Math.max(0,Number(r.exercise.workoutMinutes)||0);r.sleep.duration=Math.max(0,Number(r.sleep.duration)||0);r.timeline=Array.isArray(r.timeline)?r.timeline.filter(b=>b&&typeof b==='object').map(b=>({id:String(b.id||uid()),label:String(b.label||'Block'),start:/^\d{2}:\d{2}$/.test(b.start)?b.start:'09:00',end:/^\d{2}:\d{2}$/.test(b.end)?b.end:'10:00',category:String(b.category||'routine')})):[];r.routine=r.routine&&typeof r.routine==='object'?r.routine:{};r.shutdown=r.shutdown&&typeof r.shutdown==='object'?r.shutdown:{};r.rescueMode=!!r.rescueMode;}
    const timer=state.appState.timer;if(timer&&typeof timer==='object'){timer.type=['Coding','Math','Workout','Custom'].includes(timer.type)?timer.type:'Coding';timer.target=Math.max(60,Number(timer.target)||7200);timer.elapsed=Math.max(0,Number(timer.elapsed)||0);timer.startedAt=Number(timer.startedAt)||null;timer.active=!!timer.active&&!!timer.startedAt;}else state.appState.timer=null;
  };
  ensureShape();
  function save(){ try{updateAchievements();localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Storage is full. Export a backup and remove large notes.','error');} }
  function record(date=todayISO()) { if(!state.dailyRecords[date]) state.dailyRecords[date]=blankRecord(date); else state.dailyRecords[date]={...blankRecord(date),...state.dailyRecords[date],prayers:{...state.dailyRecords[date].prayers},coding:{...blankRecord(date).coding,...state.dailyRecords[date].coding},math:{...blankRecord(date).math,...state.dailyRecords[date].math},exercise:{...blankRecord(date).exercise,...state.dailyRecords[date].exercise},dopamine:{...blankRecord(date).dopamine,...state.dailyRecords[date].dopamine},sleep:{...blankRecord(date).sleep,...state.dailyRecords[date].sleep},stream:{...blankRecord(date).stream,...state.dailyRecords[date].stream},journal:{...blankRecord(date).journal,...state.dailyRecords[date].journal},rescue:{...blankRecord(date).rescue,...state.dailyRecords[date].rescue}}; return state.dailyRecords[date]; }
  function ensureCycle(){if(!state.profile.startDate)return;let cycle=state.cycles.find(c=>c.id===state.currentCycleId);if(!cycle){cycle={id:uid(),startDate:state.profile.startDate,createdAt:new Date().toISOString(),label:'14-Day Rebuild Protocol'};state.cycles.push(cycle);state.currentCycleId=cycle.id;save();}return cycle;}
  ensureCycle();

  // 3. Date and protocol utilities
  function protocolDay(date=todayISO()){const start=state.profile.startDate||date;return dayDiff(start,date)+1;}
  function phaseFor(day){return PHASES.find(p=>day>=p.from&&day<=p.to)||PHASES[0];}
  function dateForDay(day,cycle=ensureCycle()){return addDays(cycle?.startDate||state.profile.startDate,day-1);}
  function currentRecord(){return record(todayISO());}
  function scoreRecord(r){const p=Object.values(r.prayers||{}).filter(Boolean).length/5;const coding=Math.min(1,(Number(r.coding.minutes)||0)/Math.max(1,state.settings.codingTarget));const math=Math.min(1,(Number(r.math.minutes)||0)/Math.max(1,state.settings.mathTarget));const body=Math.min(1,((Number(r.exercise.walking)||0)+(Number(r.exercise.workoutMinutes)||0))/Math.max(1,state.settings.exerciseTarget));const dopamine=r.dopamine.protected?1:0;const sleep=(Number(r.sleep.duration)||0)>=Number(state.profile.sleepTarget||7.5)?1:0;return Math.round(p*25+coding*25+math*15+body*15+dopamine*10+sleep*10);}
  function objectives(r){return [Object.values(r.prayers).filter(Boolean).length===5,(+r.coding.minutes||0)>=state.settings.codingTarget,(+r.math.minutes||0)>=state.settings.mathTarget,((+r.exercise.walking||0)+(+r.exercise.workoutMinutes||0))>=state.settings.exerciseTarget,!!r.dopamine.protected,(+r.sleep.duration||0)>=+state.profile.sleepTarget];}
  function scoreName(n){return n<40?'Reset':n<60?'Building':n<80?'Strong':n<95?'Locked In':'Complete Day';}
  function meaningfulRecord(r){return !!(r.closedDay||r.rescueMode||Object.values(r.prayers||{}).some(Boolean)||r.coding?.minutes||r.coding?.mission||r.coding?.tasks?.length||r.math?.minutes||r.math?.questions||r.exercise?.workout||r.exercise?.walking||r.exercise?.workoutMinutes||r.dopamine?.protected||r.sleep?.duration||r.journal?.completed||r.stream?.watched);}
  function updateAchievements(){if(!Array.isArray(state.achievements))state.achievements=[];const records=Object.values(state.dailyRecords||{}),coding=records.reduce((n,r)=>n+(+r.coding?.minutes||0),0),questions=records.reduce((n,r)=>n+(+r.math?.questions||0),0),defs=[['first-day','First Complete Day',()=>records.some(r=>scoreRecord(r)>=100)],['three-day-streak','3-Day Streak',()=>streakFor(r=>objectives(r).some(Boolean)||r.rescueMode).best>=3],['seven-day-streak','7-Day Streak',()=>streakFor(r=>objectives(r).some(Boolean)||r.rescueMode).best>=7],['ten-coding-hours','10 Coding Hours',()=>coding>=600],['hundred-questions','100 Math Questions',()=>questions>=100],['perfect-prayer','First Perfect Prayer Day',()=>records.some(r=>Object.values(r.prayers||{}).filter(Boolean).length===5)],['first-feature','First Project Feature Finished',()=>state.profile.features?.some(f=>typeof f==='object'&&f.done)],['project-shipped','Project Shipped',()=>state.profile.projectStatus==='Shipped'],['protocol-complete','14-Day Protocol Completed',()=>protocolDay()>14]];for(const [id,title,test] of defs){if(!state.achievements.some(a=>a.id===id)&&test())state.achievements.push({id,title,unlockedAt:todayISO()});}}
  function currentStreak(){let n=0,d=todayISO();for(let i=0;i<365;i++){const r=state.dailyRecords[d];if(!r||(!objectives(r).some(Boolean)&&!r.rescueMode))break;n++;d=addDays(d,-1);}return n;}
  function streakFor(test){let run=0,best=0,previous=null,dates=Object.keys(state.dailyRecords).sort();for(const d of dates){if(test(state.dailyRecords[d])){run=previous&&dayDiff(previous,d)===1?run+1:1;best=Math.max(best,run);}else run=0;previous=d;}const latest=dates.at(-1);return {current:latest===todayISO()?run:0,best};}
  function remainingPrayer(){const r=currentRecord(), now=new Date();const current=now.getHours()*60+now.getMinutes();return PRAYERS.map(name=>({name,time:state.profile.prayerTimes[name],mins:(()=>{const [h,m]=(state.profile.prayerTimes[name]||'00:00').split(':').map(Number);return h*60+m;})(),done:!!r.prayers[name]})).filter(p=>!p.done&&p.mins>=current).sort((a,b)=>a.mins-b.mins)[0]||PRAYERS.map(name=>({name,time:state.profile.prayerTimes[name],mins:(()=>{const [h,m]=(state.profile.prayerTimes[name]||'00:00').split(':').map(Number);return h*60+m;})(),done:!!r.prayers[name]})).filter(p=>!p.done).sort((a,b)=>a.mins-b.mins)[0]||null;}
  function prayerCountdown(prayer){if(!prayer)return '';const now=new Date(),current=now.getHours()*60+now.getMinutes();let delta=prayer.mins-current;if(delta<0)delta+=1440;return `in ${Math.floor(delta/60)}h ${delta%60}m`;}
  function nextAction(r){const prayer=remainingPrayer();if(prayer)return {text:`${prayer.name} is your next prayer at ${fmtTime(prayer.time)}.`,label:'Open prayer card',action:'jump-prayers'};if(+r.coding.minutes<state.settings.codingTarget)return {text:`Start ${mins(state.settings.codingTarget-r.coding.minutes)} of coding to complete today's build target.`,label:'Start coding',action:'start-coding'};if(+r.math.minutes<state.settings.mathTarget)return {text:`Math is your next major objective. ${mins(state.settings.mathTarget-r.math.minutes)} remain.`,label:'Start math',action:'start-math'};if((+r.exercise.walking||0)+(+r.exercise.workoutMinutes||0)<state.settings.exerciseTarget)return {text:'Movement is your final major objective today.',label:'Log movement',action:'log-walk'};if(!r.dopamine.protected)return {text:'Protect your attention through the first productive hours.',label:'Mark protected',action:'protect'};if(!r.closedDay)return {text:'Your core objectives are in place. Close the day with a short review.',label:'Close day',action:'close-day'};return {text:'The day is logged. Stay with the plan.',label:'View journal',action:'go-journal'};}

  // 4. Toasts, reusable UI and navigation
  function toast(message,type='info'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),3600);}
  function navButton([id,label,icon],active){return `<button class="nav-button ${active===id?'active':''}" data-page="${id}" aria-current="${active===id?'page':'false'}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></button>`;}
  function renderShell(){const page=state.appState.page||'today';$('#sidebar').innerHTML=`<div class="brand"><div class="brand-mark">R</div><div><div class="brand-name">REBUILD OS</div><div class="brand-sub">14-DAY PROTOCOL</div></div></div><div class="nav-label">Workspace</div><div class="nav-list">${NAV.map(n=>navButton(n,page)).join('')}</div><div class="sidebar-bottom"><div class="cycle-mini"><div class="cycle-mini-head"><span>Cycle progress</span><span>Day ${Math.min(14,Math.max(1,protocolDay()))}/14</span></div><div class="mini-days">${Array.from({length:14},(_,i)=>`<span class="mini-day ${state.dailyRecords[dateForDay(i+1)]&&scoreRecord(record(dateForDay(i+1)))>=60?'done':''} ${i+1===protocolDay()?'current':''}"></span>`).join('')}</div></div><div class="profile-chip"><div class="avatar">${esc((state.profile.name||'R').slice(0,1).toUpperCase())}</div><div><div class="profile-name">${esc(state.profile.name||'Your profile')}</div><div class="profile-caption">Personal workspace</div></div></div></div>`;
    $('#mobile-nav').innerHTML=NAV.map(n=>navButton(n,page)).join('');
    const headings={today:fmtDate(todayISO()),protocol:`Day ${Math.max(1,protocolDay())} · ${phaseFor(protocolDay()).name}`,focus:'Deep Work',journal:'Daily Journal',analytics:'Cycle Performance',settings:'Settings'};
    $('#topbar').innerHTML=`<div class="topbar-context">${esc(headings[page]||'REBUILD OS')}</div><div class="topbar-actions"><span class="topbar-date">${esc(fmtDate(todayISO(),{month:'short',day:'numeric',year:'numeric'}))}</span><button class="icon-button" data-action="command" aria-label="Open command palette">⌘ K</button><button class="icon-button" data-action="quick-add" aria-label="Quick add">＋ <span>Quick add</span></button></div>`;
  }
  function setPage(page){state.appState.page=page;state.appState.focusMode=false;document.body.classList.remove('focus-mode');save();render();$('#view').focus({preventScroll:true});}
  function pageHead(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(state.profile.name?`REBUILD OS / ${phaseFor(protocolDay()).name}`:'REBUILD OS')}</div><h1>${title}</h1><p class="page-sub">${sub}</p></div><div class="head-actions">${actions}</div></div>`;}

  // 5. Today rendering helpers
  function ring(value,day){return `<div class="ring" style="--value:${Math.max(0,Math.min(100,value))}"><svg viewBox="0 0 100 100" role="img" aria-label="${value}% daily completion"><circle class="track" cx="50" cy="50" r="42"></circle><circle class="fill" cx="50" cy="50" r="42"></circle></svg><div class="ring-center"><div class="ring-day">Day ${day}</div><div class="ring-value">${value}%</div></div></div>`;}
  function quoteFor(day){const q=['Start before you feel ready.','Finish what you started.','No zero day.','Protect the first hours.','One project. One day. One mission.','Build proof.'];return q[(Math.max(1,day)-1)%q.length];}
  function prayerCard(r){const next=remainingPrayer();const completed=Object.values(r.prayers).filter(Boolean).length;return `<section class="card" id="prayers"><div class="card-head"><div><div class="card-title">Prayer</div><div class="card-caption">${completed} / 5 completed${next?` · Next: ${esc(next.name)} at ${esc(fmtTime(next.time))} · <span data-prayer-countdown>${prayerCountdown(next)}</span>`:''}</div></div><button class="link-button" data-action="edit-prayer-times">Edit times</button></div><div class="prayer-list">${PRAYERS.map(p=>`<label class="prayer-item ${r.prayers[p]?'done':''} ${next?.name===p?'next':''}"><div class="prayer-name">${p}</div><div class="prayer-time">${esc(fmtTime(state.profile.prayerTimes[p]))}</div><input class="prayer-toggle" type="checkbox" data-prayer="${p}" aria-label="Mark ${p} complete" ${r.prayers[p]?'checked':''}>${r.prayers[p]&&r.prayerCompletedAt?.[p]?`<div class="tiny quiet" style="margin-top:5px">${new Date(r.prayerCompletedAt[p]).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</div>`:''}</label>`).join('')}</div><div class="progress-label"><span>Daily prayer rhythm</span><span>${completed*20}%</span></div><div class="progress"><span style="--progress:${completed*20}%"></span></div></section>`;}
  function codingCard(r){const tasks=r.coding.tasks||[];return `<section class="card" id="coding"><div class="card-head"><div><div class="card-title">Build</div><div class="card-caption">${esc(state.profile.projectName||'Choose your project')} · ${mins(r.coding.minutes)} focused today</div></div><span class="pill accent">${mins(state.settings.codingTarget)} target</span></div><div class="mission-box"><div class="mission-label">Today's main mission</div><div class="mission-value">${esc(r.coding.mission||r.lockIn.mission||'Set one outcome that moves the project forward.')}</div></div><div class="progress-label"><span>Focused time</span><span>${mins(r.coding.minutes)} / ${mins(state.settings.codingTarget)}</span></div><div class="progress"><span style="--progress:${Math.min(100,r.coding.minutes/state.settings.codingTarget*100)}%"></span></div><div class="task-list">${tasks.length?tasks.map((t,i)=>`<div class="task"><input class="objective-check" type="checkbox" data-task-check="${esc(t.id)}" ${t.done?'checked':''} aria-label="Complete ${esc(t.text)}"><span class="task-label ${t.done?'completed':''}">${esc(t.text)}</span>${t.done?`<span class="task-time">${esc(t.completedAt||'Done')}</span>`:''}<button class="task-remove" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Edit task">Edit</button><button class="task-remove" data-action="reorder-task" data-id="${esc(t.id)}" data-direction="up" aria-label="Move task up" ${i===0?'disabled':''}>↑</button><button class="task-remove" data-action="reorder-task" data-id="${esc(t.id)}" data-direction="down" aria-label="Move task down" ${i===tasks.length-1?'disabled':''}>↓</button><button class="task-remove" data-action="delete-task" data-id="${esc(t.id)}" aria-label="Delete task">×</button></div>`).join(''):`<div class="empty-state"><strong>Define the one thing that must be finished today.</strong>Add supporting tasks when useful.</div>`}</div><div class="action-row"><button class="btn primary sm" data-action="start-coding">Start Focus</button><button class="btn sm" data-action="quick-log" data-kind="coding">Quick Log</button><button class="btn sm" data-action="add-task">＋ Task</button><button class="btn ghost sm" data-action="lock-in">Lock in today</button></div></section>`;}
  function mathCard(r){const topics=state.profile.topics||[];const total=topics.length,done=topics.filter(t=>t.done).length;return `<section class="card" id="math"><div class="card-head"><div><div class="card-title">Math preparation</div><div class="card-caption">${esc(state.profile.examName||'Study tracker')}${state.profile.examDate?` · target ${esc(fmtDate(state.profile.examDate,{month:'short',day:'numeric'}))}`:''}</div></div><button class="link-button" data-page="analytics">${done}/${total} topics</button></div><div class="grid grid-3"><div><div class="large-number">${mins(r.math.minutes)}</div><div class="metric-label">Studied today</div></div><div><div class="large-number">${r.math.questions||0}</div><div class="metric-label">Questions today</div></div><div><div class="large-number">${total?Math.round(done/total*100):0}%</div><div class="metric-label">Topic progress</div></div></div><div class="action-row"><button class="btn primary sm" data-action="start-math">Start Math Session</button><button class="btn sm" data-action="quick-log" data-kind="math">Quick Log</button><button class="btn sm" data-action="add-topic">＋ Topic</button><button class="btn sm" data-action="question">＋1 Question</button></div></section>`;}
  function bodyCard(r){const total=(+r.exercise.walking||0)+(+r.exercise.workoutMinutes||0);return `<section class="card" id="body"><div class="card-head"><div><div class="card-title">Body</div><div class="card-caption">${esc(r.exercise.type||state.profile.exerciseType)} · movement today</div></div><span class="pill">${total} / ${state.settings.exerciseTarget}m</span></div><div class="progress"><span style="--progress:${Math.min(100,total/state.settings.exerciseTarget*100)}%"></span></div><div class="grid grid-3" style="margin-top:15px"><div><div class="large-number">${r.exercise.walking||0}</div><div class="metric-label">Walk min</div></div><div><div class="large-number">${r.exercise.workoutMinutes||0}</div><div class="metric-label">Workout min</div></div><div><div class="large-number">${esc(r.exercise.steps||'—')}</div><div class="metric-label">Steps</div></div></div><div class="action-row"><button class="btn primary sm" data-action="log-walk">＋ Walk</button><button class="btn sm" data-action="workout">Log workout</button><button class="btn sm" data-action="start-workout">Timer</button></div></section>`;}
  function dopamineCard(r){return `<section class="card" id="attention"><div class="card-head"><div><div class="card-title">Attention</div><div class="card-caption">Protect your first productive hours.</div></div><span class="pill ${r.dopamine.protected?'accent':''}">${r.dopamine.protected?'Protected':'In progress'}</span></div><label class="check-row"><input type="checkbox" data-dopamine="protected" ${r.dopamine.protected?'checked':''}> Protected my first productive hours</label><hr class="section-divider"><div class="grid" style="gap:9px"><label class="check-row"><input type="checkbox" data-dopamine="gaming" ${r.dopamine.gaming?'checked':''}> No gaming before work</label><label class="check-row"><input type="checkbox" data-dopamine="anime" ${r.dopamine.anime?'checked':''}> No anime before work</label><label class="check-row"><input type="checkbox" data-dopamine="scrolling" ${r.dopamine.scrolling?'checked':''}> No mindless scrolling before work</label></div></section>`;}
  function sleepCard(r){return `<section class="card" id="sleep"><div class="card-head"><div><div class="card-title">Sleep</div><div class="card-caption">Target ${esc(fmtTime(state.profile.sleepTime))} to ${esc(fmtTime(state.profile.wakeTime))}</div></div><span class="pill ${r.sleep.duration>=state.profile.sleepTarget?'accent':''}">${r.sleep.duration?`${Number(r.sleep.duration).toFixed(1)}h`:'Not logged'}</span></div><div class="field-row"><div class="field"><label for="sleep-bed">Sleep time</label><input id="sleep-bed" class="input" type="time" data-sleep="bedtime" value="${esc(r.sleep.bedtime)}"></div><div class="field"><label for="sleep-wake">Wake time</label><input id="sleep-wake" class="input" type="time" data-sleep="wakeTime" value="${esc(r.sleep.wakeTime)}"></div></div><div class="progress-label"><span>Estimated duration</span><span>${r.sleep.duration?`${Number(r.sleep.duration).toFixed(1)} / ${Number(state.profile.sleepTarget).toFixed(1)}h`:'Log both times'}</span></div><div class="progress"><span style="--progress:${Math.min(100,(r.sleep.duration/state.profile.sleepTarget)*100)}%"></span></div></section>`;}
  function scoreCard(r){const parts=[['Prayer',Object.values(r.prayers).filter(Boolean).length,5],['Build',r.coding.minutes,state.settings.codingTarget,'m'],['Math',r.math.minutes,state.settings.mathTarget,'m'],['Body',(r.exercise.walking||0)+(r.exercise.workoutMinutes||0),state.settings.exerciseTarget,'m'],['Attention',r.dopamine.protected?'Protected':'Open'],['Sleep',r.sleep.duration?`${r.sleep.duration}h`:'Not logged']];return `<section class="card"><div class="card-head"><div><div class="card-title">Daily scorecard</div><div class="card-caption">Consistency over perfection</div></div><span class="pill accent">${scoreName(scoreRecord(r))}</span></div><div class="scorecard">${parts.map(([label,a,b,u])=>`<div class="score-line"><span>${label}</span><span>${b!==undefined?`${a}${u||''} / ${b}${u||''}`:a}</span></div>`).join('')}<div class="score-total"><span>Discipline Score</span><strong>${scoreRecord(r)} <span class="small muted">/ 100</span></strong></div></div></section>`;}
  function streamCard(r){return `<section class="card" id="stream"><div class="card-head"><div><div class="card-title">Tonight's stream</div><div class="card-caption">${esc(fmtTime(state.profile.streamStart))} – ${esc(fmtTime(state.profile.streamEnd))}</div></div><label class="check-row small"><input type="checkbox" data-stream="watched" ${r.stream.watched?'checked':''}> Watched</label></div><div class="stream-prompts"><div class="stream-prompt"><label for="stream-learn">What did I learn?</label><input id="stream-learn" data-stream="learned" value="${esc(r.stream.learned)}" placeholder="A useful concept or technique"></div><div class="stream-prompt"><label for="stream-useful">What idea was useful?</label><input id="stream-useful" data-stream="useful" value="${esc(r.stream.useful)}" placeholder="Why it matters"></div><div class="stream-prompt"><label for="stream-tomorrow">What will I implement tomorrow?</label><input id="stream-tomorrow" data-stream="tomorrow" value="${esc(r.stream.tomorrow)}" placeholder="Tomorrow's action item"></div></div></section>`;}
  function miniCycle(){const cycle=ensureCycle();return `<section class="card flat"><div class="card-head"><div><div class="card-title">14-day cycle</div><div class="card-caption">Select a day to review its record</div></div><button class="link-button" data-page="protocol">Open protocol</button></div><div class="cycle-row">${Array.from({length:14},(_,i)=>{const d=i+1,date=dateForDay(d,cycle),r=state.dailyRecords[date];const done=r&&scoreRecord(r)>=80;const partial=r&&objectives(r).some(Boolean);return `<button class="day-chip ${done?'done':partial?'partial':''} ${r?.rescueMode?'rescued':''} ${d===protocolDay()?'current':''}" data-action="open-day" data-day="${d}" aria-label="Day ${d}${r?`, score ${scoreRecord(r)}`:''}">${d}</button>`;}).join('')}</div></section>`;}
  function timelineCard(r){if(!state.settings.timeline)return '';const blocks=r.timeline?.length?r.timeline:DEFAULT_ROUTINE.map((b,i)=>({id:`default-${i}`,label:b[0],start:b[1],end:b[2],category:b[3]}));const now=new Date(),m=now.getHours()*60+now.getMinutes();const active=blocks.find(b=>{const [h1,m1]=b.start.split(':').map(Number),[h2,m2]=b.end.split(':').map(Number);const s=h1*60+m1,e=h2*60+m2;return e<s?(m>=s||m<e):(m>=s&&m<e);});return `<section class="card"><div class="card-head"><div><div class="card-title">Daily timeline</div><div class="card-caption">Current block highlighted from local time</div></div><button class="link-button" data-action="add-routine">＋ Block</button></div><div class="timeline">${blocks.map((b,i)=>`<div class="timeline-row ${active?.id===b.id?'current':''}"><span class="timeline-time">${esc(b.start)}</span><span>${esc(b.label)} ${active?.id===b.id?'<span class="mini-badge">Now</span>':''}</span><label class="check-row"><input type="checkbox" data-routine-check="${esc(b.id)}" ${r.routine[b.id]?'checked':''}><span class="sr-only">Complete ${esc(b.label)}</span></label></div>`).join('')}</div><div class="action-row"><button class="btn sm" data-action="edit-routine">Customize timeline</button></div></section>`;}
  function remindersCard(r){if(!state.settings.notifications)return `<section class="card"><div class="card-head"><div class="card-title">In-app reminders</div><span class="pill">Off</span></div><div class="small muted">Enable reminders in Settings when you want quiet prompts.</div></section>`;const reminders=[];if(Object.values(r.prayers).filter(Boolean).length<5){const p=remainingPrayer();if(p)reminders.push(`${p.name} is next at ${fmtTime(p.time)}.`);}if(r.math.minutes<state.settings.mathTarget)reminders.push(`Math target has ${mins(state.settings.mathTarget-r.math.minutes)} remaining.`);if(!r.stream.tomorrow)reminders.push("Tonight's stream action item is empty.");if(!r.closedDay&&new Date().getHours()>=20)reminders.push('Complete your shutdown review before sleep.');return `<section class="card"><div class="card-head"><div><div class="card-title">Reminders</div><div class="card-caption">Quiet prompts based on today's plan</div></div><span class="pill">${reminders.length} active</span></div>${reminders.length?`<div class="insight-list">${reminders.slice(0,3).map(x=>`<div class="insight">${esc(x)}</div>`).join('')}</div>`:'<div class="small muted">No reminders right now. Keep your attention on the work.</div>'}</section>`;}
  function achievementsCard(){const items=(state.achievements||[]).slice(-4).reverse();return `<section class="card"><div class="card-head"><div><div class="card-title">Milestones</div><div class="card-caption">Evidence worth keeping</div></div><span class="pill">${state.achievements.length} unlocked</span></div>${items.length?`<div class="objective-list">${items.map(a=>`<div class="objective-row"><div class="objective-main"><span class="status-dot"></span><div><div class="objective-name">${esc(a.title)}</div><div class="objective-detail">${esc(fmtDate(a.unlockedAt,{month:'short',day:'numeric'}))}</div></div></div></div>`).join('')}</div>`:'<div class="empty-state"><strong>Your first milestone will appear here.</strong>Every record begins with one completed action.</div>'}</section>`;}
  function todayView(){const d=protocolDay(),phase=phaseFor(d),cycle=ensureCycle(),proofDate=dateForDay(14,cycle);if(d>14||state.dailyRecords[proofDate]?.closedDay)return `${pageHead('Protocol complete','Your 14-day cycle is preserved. Review the record or begin again.',`<button class="btn" data-page="protocol">Review protocol</button>`)}${completionScreen(cycle)}`;const r=currentRecord(),score=scoreRecord(r),done=objectives(r).filter(Boolean).length,next=nextAction(r);r.score=score;save();const rescued=r.rescueMode;return `${pageHead('Today',`${esc(fmtDate(todayISO()))} · Day ${Math.max(1,d)} of 14 · ${phase.name}`,`<button class="btn" data-action="copy-summary">Copy Daily Summary</button><button class="btn" data-action="close-day">Close Day</button>`)}${rescued?`<div class="rescue-banner" style="margin-bottom:15px"><div><strong>Rescue mode is active.</strong><div class="small muted">Keep the actions small. Zero avoided.</div></div><button class="btn sm" data-action="exit-rescue">Exit rescue</button></div>`:''}<div class="today-layout"><div class="main-stack"><section class="card hero-card"><div class="hero-top"><div><div class="eyebrow">${esc(phase.name)} · DAY ${Math.max(1,d)}</div><div class="greeting">Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.profile.name||'there')}.</div><div class="hero-copy">${esc(phase.focus)}</div><div class="hero-quote">${quoteFor(d)}</div></div>${ring(done/6*100,Math.max(1,d))}</div><div class="hero-bottom"><div class="hero-stats"><div class="hero-stat"><div class="large-number">${score}</div><div class="metric-label">Discipline score</div></div><div class="hero-stat"><div class="large-number">${currentStreak()}d</div><div class="metric-label">Showed-up streak</div></div><div class="hero-stat"><div class="large-number">${done}<span class="small muted"> / 6</span></div><div class="metric-label">Objectives complete</div></div></div><button class="btn sm" data-action="lock-in">Lock in today</button></div></section><section class="card next-action"><div><div class="eyebrow">Next action</div><div class="next-action-text">${esc(next.text)}</div></div><button class="btn primary sm" data-action="${next.action}">${esc(next.label)}</button></section>${rescued?rescuePanel(r):''}${prayerCard(r)}${codingCard(r)}${mathCard(r)}<div class="grid grid-2">${bodyCard(r)}${dopamineCard(r)}</div><div class="grid grid-2">${sleepCard(r)}${streamCard(r)}</div>${timelineCard(r)}${remindersCard(r)}${achievementsCard()}${miniCycle()}</div><aside class="side-stack">${scoreCard(r)}<section class="card"><div class="card-head"><div><div class="card-title">Project</div><div class="card-caption">One project until shipped.</div></div><button class="link-button" data-page="settings">Edit</button></div><div class="mission-value">${esc(state.profile.projectName||'Name your project')}</div><p class="small muted">${esc(state.profile.projectSummary||'Keep the scope clear. Ship a useful version.')}</p><div class="progress-label"><span>Core features</span><span>${(state.profile.features||[]).filter(f=>f.done).length||0} / 3</span></div><div class="feature-list">${(state.profile.features||['','','']).map((f,i)=>`<label class="check-row"><input type="checkbox" data-feature="${i}" ${f.done?'checked':''} ${!f.text?'disabled':''}> ${esc(f.text||`Feature ${i+1} not defined`)}</label>`).join('')}</div><div class="action-row"><button class="btn sm" data-page="settings">Project details</button></div></section><section class="card"><div class="card-head"><div><div class="card-title">Daily status</div><div class="card-caption">Based on today's entries</div></div></div><p class="small muted">${esc(smartStatus(r))}</p><div class="action-row"><button class="btn sm" data-action="rescue">Rescue This Day</button><button class="btn sm" data-action="focus-mode">Enter Focus Mode</button></div></section><section class="card"><div class="card-head"><div><div class="card-title">Shutdown</div><div class="card-caption">A small close to the day</div></div><span class="pill">${fmtTime(state.profile.sleepTime)}</span></div>${['Tomorrow mission selected','Stream note saved','Journal complete','Desk reset','Sleep time confirmed'].map((x,i)=>`<label class="check-row" style="margin:9px 0"><input type="checkbox" data-shutdown="${i}" ${r.shutdown?.[i]?'checked':''}> ${x}</label>`).join('')}</section></aside></div>`;}
  function smartStatus(r){const done=objectives(r).filter(Boolean).length;if(r.rescueMode&&!Object.values(r.rescue).every(Boolean))return 'Today is in Rescue Mode. Complete the remaining small actions to avoid a zero day.';if(done>=6)return 'All six daily objectives are complete. Close the day and capture what worked.';if(r.dopamine.protected&&r.math.minutes>=state.settings.mathTarget)return 'Attention and math are protected. Keep your next work block simple.';if(r.coding.minutes<state.settings.codingTarget)return `${done}/6 objectives complete. Build time needs ${mins(state.settings.codingTarget-r.coding.minutes)} more.`;if(done===5)return 'One objective remains. Finish it with a short, deliberate block.';return `${done}/6 objectives complete. Choose the next action and keep the day moving.`;}
  function rescuePanel(r){return `<section class="card"><div class="card-head"><div><div class="card-title">Rescue checklist</div><div class="card-caption">Small actions to keep the day alive</div></div></div><div class="rescue-check">${[['prayer','Complete next prayer'],['coding','30 min coding'],['math','20 min math'],['walk','10 min walk']].map(([k,label])=>`<label class="check-row"><input type="checkbox" data-rescue="${k}" ${r.rescue[k]?'checked':''}> ${label}</label>`).join('')}</div>${Object.values(r.rescue).every(Boolean)?'<div class="pill accent">Zero avoided. Day rescued.</div>':''}</section>`;}

  // 6. Protocol, focus, journal and analytics views
  function protocolView(){const cycle=ensureCycle(),day=protocolDay(),proofDate=dateForDay(14,cycle),proofDone=!!state.dailyRecords[proofDate]?.closedDay;return `${pageHead('The 14-day protocol','Four phases. One deliberate cycle. Past records stay editable.',`<button class="btn" data-action="new-cycle">Start new cycle</button>`)}${day>14||proofDone?completionScreen(cycle):''}<section class="card" style="margin-bottom:15px"><div class="card-head"><div><div class="card-title">${esc(fmtDate(cycle.startDate,{month:'long',day:'numeric',year:'numeric'}))} → ${esc(fmtDate(addDays(cycle.startDate,13),{month:'long',day:'numeric',year:'numeric'}))}</div><div class="card-caption">${Math.min(14,Math.max(0,day))} days elapsed in this cycle</div></div><span class="protocol-phase">${esc(phaseFor(Math.min(14,Math.max(1,day))).name)}</span></div><div class="progress"><span style="--progress:${Math.min(100,Math.max(0,day)/14*100)}%"></span></div></section>${PHASES.map(phase=>`<h2 class="phase-title">${esc(phase.name)} <span class="quiet small">· Days ${phase.from}–${phase.to}</span></h2><div class="protocol-grid">${Array.from({length:phase.to-phase.from+1},(_,i)=>{const n=phase.from+i,date=dateForDay(n,cycle),r=state.dailyRecords[date],score=r?scoreRecord(r):0,stateName=n===day?'current':n<day?(r?'completed':''):'',theme=DAY_THEMES[n-1];return `<button class="protocol-day ${stateName} ${r?.rescueMode?'rescued':''}" data-action="open-day" data-day="${n}"><div class="protocol-day-top"><span>DAY ${String(n).padStart(2,'0')}</span><span>${r?`${score}/100`:n===day?'CURRENT':'UPCOMING'}</span></div><h3>${n===14?'Proof day':theme}</h3><p>${r?`${objectives(r).filter(Boolean).length}/6 objectives · ${r.rescueMode?'Rescued · ':''}${r.closedDay?'Reviewed':'In progress'}`:n===day?phase.focus:'Open the day plan and record what gets done.'}</p></button>`;}).join('')}</div>`).join('')}`;}
  function completionScreen(cycle){const dates=Array.from({length:14},(_,i)=>dateForDay(i+1,cycle)),records=dates.map(d=>state.dailyRecords[d]).filter(Boolean),score=records.length?Math.round(records.reduce((n,r)=>n+scoreRecord(r),0)/records.length):0,prayers=records.reduce((n,r)=>n+Object.values(r.prayers||{}).filter(Boolean).length,0),coding=records.reduce((n,r)=>n+(+r.coding.minutes||0),0),math=records.reduce((n,r)=>n+(+r.math.minutes||0),0),questions=records.reduce((n,r)=>n+(+r.math.questions||0),0),workouts=records.filter(r=>r.exercise.workout).length,rescued=records.filter(r=>r.rescueMode).length;return `<section class="card completion-screen" style="margin-bottom:15px"><div class="eyebrow">Fourteen days of evidence</div><h1>PROTOCOL COMPLETE</h1><p>14 days ago you started rebuilding the system. Here is the proof.</p><div class="analytics-kpis" style="margin:24px 0;text-align:left">${[['Avg score',`${score}`],['Prayers',`${prayers}`],['Coding',mins(coding)],['Math',mins(math)],['Questions',questions],['Workouts',workouts],['Rescued',rescued],['Best streak',`${streakFor(r=>objectives(r).some(Boolean)||r.rescueMode).best}d`]].map(([l,v])=>`<div class="kpi"><div class="large-number">${v}</div><div class="metric-label">${l}</div></div>`).join('')}</div><div class="action-row" style="justify-content:center"><button class="btn" data-page="protocol">Review Protocol</button><button class="btn" data-action="export-report">Export Report</button><button class="btn primary" data-action="new-cycle">Start Next Cycle</button></div></section>`;}
  function focusElapsed(){const t=state.appState.timer;if(!t)return 0;return t.elapsed+(t.active?Math.max(0,Math.floor((Date.now()-t.startedAt)/1000)):0);}
  function focusView(){const t=state.appState.timer||{type:'Coding',target:120*60,elapsed:0,active:false,notes:'',task:''};const elapsed=focusElapsed(),remaining=Math.max(0,t.target-elapsed),percent=Math.min(100,elapsed/Math.max(1,t.target)*100);const sessions=state.focusSessions.slice().reverse().slice(0,8);return `${pageHead('Deep Work','One focused block at a time.',`<button class="btn" data-action="focus-mode">${state.appState.focusMode?'Exit Focus Mode':'Enter Focus Mode'}</button>`)}<div class="focus-layout"><section class="card focus-card"><div class="focus-mode-select">${['Coding','Math','Workout','Custom'].map(m=>`<button class="mode-chip ${t.type===m?'active':''}" data-action="timer-mode" data-mode="${m}">${m}</button>`).join('')}</div><div class="eyebrow">${t.active?'SESSION IN PROGRESS':elapsed?'SESSION PAUSED':'READY WHEN YOU ARE'}</div><div class="timer-display" id="timer-display">${durationLabel(remaining)}</div><div class="timer-sub">${esc(t.type)} · ${Math.floor(elapsed/60)} min elapsed · ${Math.floor(t.target/60)} min target</div><div class="timer-progress"><div class="progress"><span id="timer-progress" style="--progress:${percent}%"></span></div></div><div class="timer-controls">${t.active?`<button class="btn primary" data-action="timer-pause">Pause</button>`:`<button class="btn primary" data-action="timer-start">${elapsed?'Resume':'Start Focus'}</button>`}<button class="btn" data-action="timer-stop">Stop & Save</button><button class="btn ghost" data-action="timer-reset">Reset</button></div><div class="grid grid-2" style="max-width:430px;margin:24px auto 0;text-align:left"><div class="field"><label for="timer-target">Target minutes</label><input id="timer-target" class="input" type="number" min="1" max="720" data-timer-field="target" value="${Math.floor(t.target/60)}"></div><div class="field"><label for="timer-task">Linked task or topic</label><input id="timer-task" class="input" data-timer-field="task" value="${esc(t.task||'')}" placeholder="Optional"></div></div><div class="field" style="max-width:430px;margin:0 auto;text-align:left"><label for="timer-notes">Session notes</label><textarea id="timer-notes" class="textarea" data-timer-field="notes" placeholder="What are you working through?">${esc(t.notes||'')}</textarea></div></section><div class="main-stack"><section class="card"><div class="card-head"><div><div class="card-title">Today in focus</div><div class="card-caption">Saved sessions count toward daily totals</div></div></div><div class="grid grid-3"><div><div class="large-number">${mins(currentRecord().coding.minutes)}</div><div class="metric-label">Coding</div></div><div><div class="large-number">${mins(currentRecord().math.minutes)}</div><div class="metric-label">Math</div></div><div><div class="large-number">${currentStreak()}d</div><div class="metric-label">Showed-up streak</div></div></div></section><section class="card"><div class="card-head"><div><div class="card-title">Recent sessions</div><div class="card-caption">${state.focusSessions.length} saved sessions</div></div></div>${sessions.length?sessions.map(s=>`<div class="session-row"><div><div class="session-title">${esc(s.type)}${s.task?` · ${esc(s.task)}`:''}</div><div class="session-meta">${esc(fmtDate(s.date,{month:'short',day:'numeric'}))} · ${s.notes?esc(s.notes):'No notes'}</div></div><div class="session-duration">${mins(s.minutes)}</div></div>`).join(''):`<div class="empty-state"><strong>Your first focused block starts here.</strong>Choose a mode and begin.</div>`}</section></div></div>`;}
  function journalView(){const r=currentRecord(),j=r.journal;return `${pageHead('Daily journal','Short notes create useful evidence. Your writing saves as you type.',`<span class="saved-status" id="journal-saved">Saved</span><button class="btn" data-action="close-day">Close Day</button>`)}<div class="grid grid-2" style="margin-bottom:15px"><section class="card"><div class="card-head"><div><div class="card-title">Check-in</div><div class="card-caption">A simple personal snapshot</div></div></div>${[['Mood','mood'],['Energy','energy'],['Stress','stress']].map(([label,key])=>`<div class="score-line" style="padding:8px 0"><span>${label}</span><span class="star-row">${[1,2,3,4,5].map(n=>`<button class="${j[key]>=n?'on':''}" data-action="rating" data-key="${key}" data-value="${n}" aria-label="${label} ${n} of 5">●</button>`).join('')}</span></div>`).join('')}</section><section class="card"><div class="card-head"><div><div class="card-title">Today's intention</div><div class="card-caption">Keep the important work visible.</div></div></div><div class="field"><label for="j-mission">Main mission</label><input class="input" id="j-mission" data-journal="morningMission" value="${esc(j.morningMission||r.coding.mission)}" placeholder="One meaningful outcome"></div><div class="field"><label for="j-must">What must happen today?</label><textarea class="textarea" id="j-must" data-journal="mustHappen" placeholder="The essential actions">${esc(j.mustHappen)}</textarea></div><div class="field"><label for="j-avoid">What will I avoid?</label><input class="input" id="j-avoid" data-journal="avoid" value="${esc(j.avoid)}" placeholder="A distraction or avoidable detour"></div></section></div><section class="card"><div class="card-head"><div><div class="card-title">Evening reflection</div><div class="card-caption">No judgment. Record what happened and adjust.</div></div></div><div class="journal-grid">${[['What did I complete?','completed'],['What distracted me?','distracted'],['What did I learn?','learned'],['What will I improve tomorrow?','improve']].map(([label,key])=>`<div class="journal-section"><h3>${label}</h3><textarea class="textarea" data-journal="${key}" placeholder="Write one honest sentence">${esc(j[key])}</textarea></div>`).join('')}</div><div class="saved-status" id="journal-saved-bottom" style="margin-top:12px">Saved locally</div></section>`;}
  function analyticsData(){const cycle=ensureCycle(),days=Array.from({length:14},(_,i)=>({n:i+1,date:dateForDay(i+1,cycle),r:state.dailyRecords[dateForDay(i+1,cycle)]}));const records=Object.values(state.dailyRecords).filter(meaningfulRecord);const completed=records.filter(r=>scoreRecord(r)>=80).length,rescued=records.filter(r=>r.rescueMode).length,zero=records.filter(r=>!objectives(r).some(Boolean)&&!r.rescueMode&&r.closedDay).length;const totals={coding:records.reduce((a,r)=>a+(+r.coding.minutes||0),0),math:records.reduce((a,r)=>a+(+r.math.minutes||0),0),questions:records.reduce((a,r)=>a+(+r.math.questions||0),0),correct:records.reduce((a,r)=>a+(+r.math.correct||0),0),incorrect:records.reduce((a,r)=>a+(+r.math.incorrect||0),0),walk:records.reduce((a,r)=>a+(+r.exercise.walking||0),0),workout:records.reduce((a,r)=>a+(+r.exercise.workoutMinutes||0),0),prayers:records.reduce((a,r)=>a+Object.values(r.prayers||{}).filter(Boolean).length,0),protected:records.filter(r=>r.dopamine.protected).length};const logged=records.length||1;const avgScore=Math.round(records.reduce((a,r)=>a+scoreRecord(r),0)/logged);const topics=state.profile.topics||[];const attempted=totals.correct+totals.incorrect;return {cycle,days,records,completed,rescued,zero,totals,logged,avgScore,topics,attempted};}
  function analyticsView(){const a=analyticsData(),prayerTotals=Object.fromEntries(PRAYERS.map(p=>[p,a.records.reduce((sum,r)=>sum+(r.prayers?.[p]?1:0),0)]));const scores=a.days.map(x=>x.r?scoreRecord(x.r):0);const best=Math.max(0,...scores);const insights=[];const weak=PRAYERS.slice().sort((x,y)=>prayerTotals[x]-prayerTotals[y])[0];if(a.records.length>=3&&prayerTotals[weak]<a.records.length)insights.push(`${weak} is currently your least consistent prayer (${prayerTotals[weak]} completions across ${a.records.length} logged days).`);if(a.totals.questions>=10)insights.push(`You have solved ${a.totals.questions} math questions with ${a.attempted?Math.round(a.totals.correct/a.attempted*100):0}% accuracy.`);if(state.focusSessions.length>=3){const avg=state.focusSessions.reduce((s,x)=>s+x.minutes,0)/state.focusSessions.length;insights.push(`Your average saved focus session is ${Math.round(avg)} minutes.`);}if(a.completed)insights.push(`${a.completed} logged day${a.completed===1?'':'s'} reached a Discipline Score of 80 or more.`);return `${pageHead('Cycle performance','A clear record of what you practiced.',`<button class="btn" data-action="export">Export Data</button>`)}<div class="analytics-kpis" style="margin-bottom:15px">${[['Average score',`${a.avgScore}`,'across logged days'],['Complete days',a.completed,'score 80+'],['Rescued days',a.rescued,'recovery counted'],['Current streak',`${currentStreak()}d`,`best ${streakFor(r=>objectives(r).some(Boolean)||r.rescueMode).best}d`]].map(([l,v,s])=>`<div class="kpi"><div class="large-number">${v}</div><div class="metric-label">${l}</div><div class="tiny quiet" style="margin-top:6px">${s}</div></div>`).join('')}</div><div class="grid grid-2" style="margin-bottom:15px"><section class="card"><div class="card-head"><div><div class="card-title">Discipline score</div><div class="card-caption">Current cycle, days 1–14</div></div></div><div class="chart-wrap"><div class="chart-bars">${scores.map((v,i)=>`<div class="chart-bar-group"><div class="chart-bar" title="Day ${i+1}: ${v}" style="--bar:${v}%"></div><span class="chart-label">${i+1}</span></div>`).join('')}</div></div></section><section class="card"><div class="card-head"><div><div class="card-title">Personal records</div><div class="card-caption">Across saved days and sessions</div></div></div><div class="scorecard">${[['Highest Discipline Score',`${best}/100`],['Longest Focus Session',`${Math.max(0,...state.focusSessions.map(s=>s.minutes))}m`],['Most Coding in One Day',`${Math.max(0,...a.records.map(r=>+r.coding.minutes||0))}m`],['Most Math Questions',`${Math.max(0,...a.records.map(r=>+r.math.questions||0))}`],['Best Overall Streak',`${streakFor(r=>objectives(r).some(Boolean)||r.rescueMode).best} days`]].map(([l,v])=>`<div class="score-line"><span>${l}</span><span>${v}</span></div>`).join('')}</div></section></div><section class="card" style="margin-bottom:15px"><div class="card-head"><div><div class="card-title">14-day consistency</div><div class="card-caption">Each cell shows completion strength. Dashed outline marks a rescued day.</div></div></div><div class="heatmap-wrap"><div class="heatmap"><span></span>${Array.from({length:14},(_,i)=>`<span class="heat-day">${i+1}</span>`).join('')}${[['Prayer',r=>Object.values(r.prayers||{}).filter(Boolean).length/5],['Coding',r=>Math.min(1,(+r.coding.minutes||0)/state.settings.codingTarget)],['Math',r=>Math.min(1,(+r.math.minutes||0)/state.settings.mathTarget)],['Exercise',r=>Math.min(1,((+r.exercise.walking||0)+(+r.exercise.workoutMinutes||0))/state.settings.exerciseTarget)],['Dopamine',r=>r.dopamine.protected?1:0],['Sleep',r=>(+r.sleep.duration||0)>=state.profile.sleepTarget?1:0]].map(([label,get])=>`<span class="heat-label">${label}</span>${a.days.map(d=>{const v=d.r?get(d.r):0,l=v===0?0:v<.4?1:v<.75?2:v<1?3:4;return `<button class="heat-cell level-${l} ${d.r?.rescueMode?'rescued':''}" data-action="open-day" data-day="${d.n}" title="Day ${d.n} · ${label}: ${Math.round(v*100)}%${d.r?.rescueMode?' · rescued':''}" aria-label="Day ${d.n}, ${label}, ${Math.round(v*100)} percent"></button>`;}).join('')}`).join('')}</div></div></section><div class="grid grid-2" style="margin-bottom:15px"><section class="card"><div class="card-head"><div><div class="card-title">Work and study</div><div class="card-caption">Accumulated from real saved records</div></div></div><div class="grid grid-2"><div><div class="large-number">${mins(a.totals.coding)}</div><div class="metric-label">Coding time</div></div><div><div class="large-number">${mins(a.totals.math)}</div><div class="metric-label">Math time</div></div><div><div class="large-number">${a.totals.questions}</div><div class="metric-label">Questions solved</div></div><div><div class="large-number">${a.attempted?Math.round(a.totals.correct/a.attempted*100):0}%</div><div class="metric-label">Question accuracy</div></div></div><hr class="section-divider"><div class="card-title">Prayer consistency</div><div class="scorecard" style="margin-top:10px">${PRAYERS.map(p=>`<div class="score-line"><span>${p}</span><span>${a.records.length?Math.round(prayerTotals[p]/a.records.length*100):0}% · ${prayerTotals[p]}</span></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><div class="card-title">Movement and attention</div><div class="card-caption">Daily actions, across all recorded days</div></div></div><div class="grid grid-2"><div><div class="large-number">${a.records.filter(r=>r.exercise.workout).length}</div><div class="metric-label">Workouts</div></div><div><div class="large-number">${mins(a.totals.walk+a.totals.workout)}</div><div class="metric-label">Movement time</div></div><div><div class="large-number">${a.totals.protected}</div><div class="metric-label">Protected mornings</div></div><div><div class="large-number">${a.zero}</div><div class="metric-label">Zero days</div></div></div><hr class="section-divider"><div class="card-title">Math topics</div><div class="topic-list" style="margin-top:8px">${a.topics.length?a.topics.map(t=>`<div class="topic-item"><span class="status-dot"></span><div><div class="topic-name">${esc(t.name)}</div><div class="topic-meta">${t.correct||0}/${(t.correct||0)+(t.incorrect||0)} correct · confidence ${t.confidence||1}/5</div></div><span class="small muted">${t.done?'Complete':'In progress'}</span></div>`).join(''):'<div class="empty-state"><strong>Add your first chapter.</strong>Topic progress will appear here.</div>'}</div></section></div><section class="card"><div class="card-head"><div><div class="card-title">Insights</div><div class="card-caption">Shown only when saved records support them</div></div></div>${insights.length?`<div class="insight-list">${insights.map(i=>`<div class="insight">${esc(i)}</div>`).join('')}</div>`:'<div class="empty-state"><strong>More data will make patterns visible.</strong>Keep recording sessions and daily objectives.</div>'}</section>`;}

  function settingsView(){const p=state.profile,s=state.settings,topics=p.topics||[];return `${pageHead('Settings','Tune the protocol to your actual schedule and work.',`<span class="saved-status">Saved</span>`)}<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${[['profile','Profile'],['project','Project'],['math-setup','Math'],['targets','Targets'],['prayer-settings','Prayer times'],['schedule','Schedule'],['appearance','Appearance'],['data','Data & backup']].map(([id,l])=>`<button class="settings-tab" data-scroll="${id}">${l}</button>`).join('')}</nav><div><section class="card settings-section" id="profile"><h2>Profile and cycle</h2><div class="field-row"><div class="field"><label>Name</label><input class="input" data-profile="name" value="${esc(p.name)}" placeholder="Your name"></div><div class="field"><label>Protocol start date</label><input class="input" type="date" data-profile="startDate" value="${esc(p.startDate)}"></div></div><p>Changing the start date changes the day labels. Existing daily records remain saved by date.</p><button class="btn sm" data-action="new-cycle">Start a new 14-day cycle</button></section><section class="card settings-section" id="project"><h2>Project finishing system</h2><div class="field-row"><div class="field"><label>Project name</label><input class="input" data-profile="projectName" value="${esc(p.projectName)}" placeholder="One project until shipped"></div><div class="field"><label>Status</label><select class="select" data-profile="projectStatus">${['Planned','Building','Testing','Shipped'].map(x=>`<option ${p.projectStatus===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>Project summary</label><input class="input" data-profile="projectSummary" value="${esc(p.projectSummary)}" placeholder="One sentence about the outcome"></div><div class="field"><label>Core features</label>${[0,1,2].map(i=>`<div class="field-row" style="align-items:center"><label class="check-row"><input type="checkbox" data-feature="${i}" ${(p.features||[])[i]?.done?'checked':''}> Complete</label><input class="input" data-feature-name="${i}" value="${esc((p.features||[])[i]?.text||'')}" placeholder="Core feature ${i+1}"></div>`).join('')}</div><div class="field"><label>Definition of DONE</label><textarea class="textarea" data-profile="doneDefinition" placeholder="What proves this project is finished?">${esc(p.doneDefinition)}</textarea></div><div class="field-row"><div class="field"><label>Deployment URL</label><input class="input" type="url" data-profile="deploymentUrl" value="${esc(p.deploymentUrl)}" placeholder="https://"></div><div class="field"><label>GitHub URL</label><input class="input" type="url" data-profile="githubUrl" value="${esc(p.githubUrl)}" placeholder="https://github.com/"></div></div><div class="field"><label>Project notes</label><textarea class="textarea" data-profile="projectNotes">${esc(p.projectNotes)}</textarea></div><button class="btn sm" data-action="ship-project">Mark project shipped</button><span class="small quiet" style="margin-left:8px">Available when all three features and deployment URL are set.</span></section><section class="card settings-section" id="math-setup"><h2>Math supply tracker</h2><div class="field-row"><div class="field"><label>Exam / supply name</label><input class="input" data-profile="examName" value="${esc(p.examName)}" placeholder="Exam or subject"></div><div class="field"><label>Target exam date</label><input class="input" type="date" data-profile="examDate" value="${esc(p.examDate)}"></div></div><div class="field"><label>Topics / chapters</label><div class="topic-list">${topics.length?topics.map(t=>`<div class="topic-item"><span class="status-dot"></span><div><div class="topic-name">${esc(t.name)}</div><div class="topic-meta">${t.questions||0} questions · ${t.correct||0} correct · studied ${t.minutes||0}m</div><div class="rating">${[1,2,3,4,5].map(n=>`<button class="${t.confidence>=n?'selected':''}" data-action="topic-rating" data-id="${esc(t.id)}" data-value="${n}" aria-label="${esc(t.name)}, confidence ${n}">●</button>`).join('')}</div></div><div><label class="check-row"><input type="checkbox" data-topic-done="${esc(t.id)}" ${t.done?'checked':''}> Done</label><button class="task-remove" data-action="delete-topic" data-id="${esc(t.id)}" aria-label="Delete topic">Remove</button></div></div>`).join(''):'<div class="empty-state"><strong>Add your first chapter.</strong>Progress and question accuracy will show here.</div>'}</div></div><button class="btn sm" data-action="add-topic">＋ Add topic</button></section><section class="card settings-section" id="targets"><h2>Daily targets</h2><div class="field-row three">${[['Coding target (minutes)','codingTarget',s.codingTarget],['Math target (minutes)','mathTarget',s.mathTarget],['Movement target (minutes)','exerciseTarget',s.exerciseTarget]].map(([l,k,v])=>`<div class="field"><label>${l}</label><input class="input" type="number" min="1" data-setting="${k}" value="${v}"></div>`).join('')}</div><div class="field-row"><div class="field"><label>Target sleep (hours)</label><input class="input" type="number" min="1" max="16" step="0.5" data-profile="sleepTarget" value="${esc(p.sleepTarget)}"></div><div class="field"><label>Preferred activity</label><select class="select" data-profile="exerciseType">${['Walking','Gym','Home workout','Mixed'].map(x=>`<option ${p.exerciseType===x?'selected':''}>${x}</option>`).join('')}</select></div></div></section><section class="card settings-section" id="prayer-settings"><h2>Manual prayer times</h2><p>Times are stored locally and never fetched from an API.</p><div class="field-row three">${PRAYERS.map(name=>`<div class="field"><label>${name}</label><input class="input" type="time" data-prayer-time="${name}" value="${esc(p.prayerTimes[name])}"></div>`).join('')}</div></section><section class="card settings-section" id="schedule"><h2>Schedule</h2><div class="field-row"><div class="field"><label>Target wake time</label><input class="input" type="time" data-profile="wakeTime" value="${esc(p.wakeTime)}"></div><div class="field"><label>Target sleep time</label><input class="input" type="time" data-profile="sleepTime" value="${esc(p.sleepTime)}"></div><div class="field"><label>Stream starts</label><input class="input" type="time" data-profile="streamStart" value="${esc(p.streamStart)}"></div><div class="field"><label>Stream ends</label><input class="input" type="time" data-profile="streamEnd" value="${esc(p.streamEnd)}"></div></div><label class="check-row"><input type="checkbox" data-setting="timeline" ${s.timeline?'checked':''}> Show daily timeline</label></section><section class="card settings-section" id="appearance"><h2>Appearance and reminders</h2><div class="field-row"><div class="field"><label>Theme</label><select class="select" data-setting="theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Dark</option><option value="light" ${s.theme==='light'?'selected':''}>Light</option></select></div><div class="field"><label>Accent</label><select class="select" data-setting="accent"><option value="green" ${s.accent==='green'?'selected':''}>Mineral green</option><option value="blue" ${s.accent==='blue'?'selected':''}>Electric blue</option><option value="cyan" ${s.accent==='cyan'?'selected':''}>Cyan</option></select></div></div><label class="check-row" style="margin:10px 0"><input type="checkbox" data-setting="notifications" ${s.notifications?'checked':''}> In-app reminders</label><label class="check-row"><input type="checkbox" data-setting="reducedMotion" ${s.reducedMotion?'checked':''}> Reduce motion</label></section><section class="card settings-section" id="data"><h2>Data and backup</h2><p>All personal data stays in this browser. Export a backup before moving devices.</p><div class="action-row"><button class="btn primary" data-action="export">Export Data</button><button class="btn" data-action="import">Import backup</button><input class="sr-only" id="import-file" type="file" accept="application/json,.json"><button class="btn" data-action="snapshot">Create snapshot</button><button class="btn danger" data-action="reset">Reset Application</button></div><div class="small quiet" style="margin-top:12px">Version ${state.version} · ${Object.keys(state.dailyRecords).length} daily records · ${state.focusSessions.length} focus sessions</div></section></div></div>`;}

  // 7. Onboarding flow
  let onboardStep=0;
  function onboarding(){if(state.appState.setupComplete)return;const steps=[
    `<div class="eyebrow">A private operating system</div><h1>Rebuild with a clear plan.</h1><p>Set the foundations for your 14-day protocol. Everything stays on this device.</p><div class="field-row"><div class="field"><label>Your name</label><input class="input" data-onboard="name" value="${esc(state.profile.name)}" placeholder="Name"></div><div class="field"><label>Protocol start date</label><input class="input" type="date" data-onboard="startDate" value="${esc(state.profile.startDate)}"></div></div><div class="field-row"><div class="field"><label>Target wake time</label><input class="input" type="time" data-onboard="wakeTime" value="${esc(state.profile.wakeTime)}"></div><div class="field"><label>Target sleep time</label><input class="input" type="time" data-onboard="sleepTime" value="${esc(state.profile.sleepTime)}"></div><div class="field"><label>Sleep target (hours)</label><input class="input" type="number" step="0.5" data-onboard="sleepTarget" value="${esc(state.profile.sleepTarget)}"></div></div>`,
    `<div class="eyebrow">Build</div><h1>Choose one project.</h1><p>Finishing one useful thing creates proof. Keep the mission small enough to ship.</p><div class="field"><label>Project name</label><input class="input" data-onboard="projectName" value="${esc(state.profile.projectName)}" placeholder="Project name"></div><div class="field"><label>One-sentence project summary</label><textarea class="textarea" data-onboard="projectSummary" placeholder="What does it help someone do?">${esc(state.profile.projectSummary)}</textarea></div><div class="field"><label>Three core features to finish</label>${[0,1,2].map(i=>`<input class="input" style="margin:4px 0" data-onboard-feature="${i}" value="${esc(state.profile.features?.[i]?.text||'')}" placeholder="Core feature ${i+1}">`).join('')}</div><div class="field"><label>Definition of DONE</label><textarea class="textarea" data-onboard="doneDefinition" placeholder="What must be true before you call this shipped?">${esc(state.profile.doneDefinition)}</textarea></div>`,
    `<div class="eyebrow">Study and movement</div><h1>Make progress measurable.</h1><p>Keep study topics visible and choose a movement plan you can repeat.</p><div class="field-row"><div class="field"><label>Exam / supply name</label><input class="input" data-onboard="examName" value="${esc(state.profile.examName)}" placeholder="Exam or subject"></div><div class="field"><label>Target exam date (optional)</label><input class="input" type="date" data-onboard="examDate" value="${esc(state.profile.examDate)}"></div></div><div class="field"><label>Topics or chapters, one per line</label><textarea class="textarea" data-onboard="topics" placeholder="Algebra&#10;Functions&#10;Probability"></textarea></div><div class="field"><label>Preferred activity</label><select class="select" data-onboard="exerciseType">${['Walking','Gym','Home workout','Mixed'].map(x=>`<option ${state.profile.exerciseType===x?'selected':''}>${x}</option>`).join('')}</select></div>`,
    `<div class="eyebrow">Prayer</div><h1>Set manual prayer times.</h1><p>No prayer-time API is used. You can adjust these times any time in Settings.</p><div class="field-row three">${PRAYERS.map(n=>`<div class="field"><label>${n}</label><input class="input" type="time" data-onboard-prayer="${n}" value="${esc(state.profile.prayerTimes[n])}"></div>`).join('')}</div>`,
    `<div class="eyebrow">Your evenings</div><h1>Shape the schedule.</h1><p>Livestream times are editable. The timeline can be customized after setup.</p><div class="field-row"><div class="field"><label>Stream starts</label><input class="input" type="time" data-onboard="streamStart" value="${esc(state.profile.streamStart)}"></div><div class="field"><label>Stream ends</label><input class="input" type="time" data-onboard="streamEnd" value="${esc(state.profile.streamEnd)}"></div></div><div class="mission-box"><div class="mission-label">Daily non-negotiables</div><div class="tag-list" style="margin-top:10px"><span class="tag">Prayer</span><span class="tag">Deep work</span><span class="tag">Math</span><span class="tag">Movement</span><span class="tag">Protected attention</span><span class="tag">Sleep</span></div></div>`,
    `<div class="completion-screen"><div class="brand-mark" style="margin:auto">R</div><h1>Your Rebuild OS is ready.</h1><p>Your plan is saved locally. Open Day 1 and choose today's main mission.</p><button class="btn primary" data-action="finish-onboarding">Open Day 1</button></div>`
  ];
  $('#modal-root').innerHTML=`<div class="onboarding"><div class="onboard-card"><div class="brand"><div class="brand-mark">R</div><div><div class="brand-name">REBUILD OS</div><div class="brand-sub">14-DAY REBUILD PROTOCOL</div></div></div><div class="onboard-progress"><span style="width:${Math.min(100,(onboardStep+1)/5*100)}%"></span></div><div class="onboard-step active">${steps[onboardStep]}</div>${onboardStep<5?`<div class="onboard-foot"><button class="btn ghost" data-action="onboard-back" ${onboardStep===0?'disabled':''}>Back</button><span class="small quiet">${onboardStep+1} of 5</span><button class="btn primary" data-action="onboard-next">${onboardStep===4?'Review setup':'Continue'}</button></div>`:''}</div></div>`;}

  // 8. Router and rendering
  function render(){if(!state.profile.topics)state.profile.topics=[];if(!state.profile.features)state.profile.features=['','',''].map(text=>({text,done:false}));if(typeof state.profile.features[0]==='string')state.profile.features=state.profile.features.map(text=>({text,done:false}));renderShell();const page=state.appState.page||'today';const renderers={today:todayView,protocol:protocolView,focus:focusView,journal:journalView,analytics:analyticsView,settings:settingsView};$('#view').innerHTML=(renderers[page]||todayView)();if(page==='analytics')$('#view').insertAdjacentHTML('beforeend',analyticsExtrasCard());document.documentElement.dataset.theme=state.settings.theme||'dark';document.documentElement.dataset.accent=state.settings.accent||'green';document.documentElement.dataset.reducedMotion=String(!!state.settings.reducedMotion);if(state.appState.focusMode)document.body.classList.add('focus-mode');onboarding();}
  function analyticsExtrasCard(){const records=Object.values(state.dailyRecords),avgSleep=records.filter(r=>+r.sleep?.duration>0).map(r=>+r.sleep.duration),avg=avgSleep.length?(avgSleep.reduce((a,b)=>a+b,0)/avgSleep.length).toFixed(1):'0.0',wake=records.filter(r=>r.sleep?.wakeTime).map(r=>{const [h,m]=r.sleep.wakeTime.split(':').map(Number);return h*60+m;});const avgWake=wake.length?`${String(Math.floor(wake.reduce((a,b)=>a+b,0)/wake.length/60)%24).padStart(2,'0')}:${String(Math.round(wake.reduce((a,b)=>a+b,0)/wake.length)%60).padStart(2,'0')}`:'—';const checks=[['Overall',r=>objectives(r).some(Boolean)||r.rescueMode],['Prayer',r=>Object.values(r.prayers||{}).filter(Boolean).length===5],['Coding',r=>(+r.coding.minutes||0)>=state.settings.codingTarget],['Math',r=>(+r.math.minutes||0)>=state.settings.mathTarget],['Exercise',r=>(+r.exercise.walking||0)+(+r.exercise.workoutMinutes||0)>=state.settings.exerciseTarget],['Protected mornings',r=>!!r.dopamine.protected]];return `<section class="card" style="margin-top:15px"><div class="card-head"><div><div class="card-title">Sleep and streaks</div><div class="card-caption">Personal patterns across saved records</div></div></div><div class="grid grid-2"><div><div class="large-number">${avg}h</div><div class="metric-label">Average logged sleep · average wake ${avgWake}</div></div><div class="scorecard">${checks.map(([name,test])=>{const s=streakFor(test);return `<div class="score-line"><span>${name}</span><span>${s.current} current · ${s.best} best</span></div>`;}).join('')}</div></div><hr class="section-divider"><div class="card-title">Unlocked milestones</div><div class="tag-list" style="margin-top:10px">${state.achievements.length?state.achievements.map(a=>`<span class="tag">${esc(a.title)} · ${esc(fmtDate(a.unlockedAt,{month:'short',day:'numeric'}))}</span>`).join(''):'<span class="small quiet">No milestones unlocked yet.</span>'}</div></section>`;}

  // 9. Accessible modal system
  let lastFocus=null;
  function openModal(title,body,submitLabel='Save',kind='',options={}){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" data-modal-backdrop><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${options.description?`<p>${esc(options.description)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div><form data-modal-form="${esc(kind)}">${body}${submitLabel?`<div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">${esc(submitLabel)}</button></div>`:''}</form></section></div>`;$('.modal', $('#modal-root'))?.focus();}
  function closeModal(){const root=$('#modal-root');if(root.querySelector('.onboarding'))return;root.innerHTML='';if(lastFocus?.focus)lastFocus.focus();}
  function addTaskModal(){openModal('Add a coding task',`<div class="field"><label for="task-text">Task</label><input class="input" id="task-text" name="text" required maxlength="180" placeholder="A concrete next step"></div>`,'Add task','task');}
  function editTaskModal(id){const task=currentRecord().coding.tasks.find(t=>t.id===id);if(task)openModal('Edit coding task',`<input type="hidden" name="id" value="${esc(task.id)}"><div class="field"><label for="task-text">Task</label><input class="input" id="task-text" name="text" required maxlength="180" value="${esc(task.text)}"></div>`,'Save task','task-edit');}
  function addTopicModal(){openModal('Add a math topic',`<div class="field"><label for="topic-name">Topic or chapter</label><input class="input" id="topic-name" name="name" required maxlength="120" placeholder="e.g. Quadratic equations"></div><div class="field"><label for="topic-notes">Notes (optional)</label><textarea class="textarea" id="topic-notes" name="notes" placeholder="What should you understand?"></textarea></div>`,'Add topic','topic');}
  function quickLogModal(kind){const cfg=kind==='coding'?['Coding minutes','Focused work completed']:kind==='math'?['Math minutes','Study time completed']:['Movement minutes','Movement completed'];openModal(`Quick log · ${kind}`,`<div class="field"><label for="log-minutes">${cfg[0]}</label><input class="input" id="log-minutes" name="minutes" type="number" min="1" max="1440" value="${kind==='math'?30:kind==='coding'?45:20}" required></div>${kind==='math'?`<div class="field"><label for="log-questions">Questions solved (optional)</label><input class="input" id="log-questions" name="questions" type="number" min="0" value="0"></div>`:''}<div class="field"><label for="log-note">Note (optional)</label><input class="input" id="log-note" name="note" maxlength="180" placeholder="What did you work on?"></div>`,'Add to today','quick-log');}
  function lockInModal(){const r=currentRecord();openModal('Lock in today',`<p>Choose the work you want to protect. You can edit it later.</p><div class="field"><label>Main coding mission</label><input class="input" name="mission" value="${esc(r.lockIn.mission||r.coding.mission)}" maxlength="180" placeholder="One meaningful outcome"></div><div class="field"><label>Today's math topic</label><input class="input" name="topic" value="${esc(r.lockIn.topic||r.math.topic)}" maxlength="120" placeholder="Topic or chapter"></div><div class="field"><label>Workout plan</label><input class="input" name="workout" value="${esc(r.lockIn.workout)}" maxlength="120" placeholder="Walk, gym, home workout"></div><div class="field"><label>Biggest distraction to avoid</label><input class="input" name="distraction" value="${esc(r.lockIn.distraction)}" maxlength="120" placeholder="Name the likely detour"></div>`,'Lock in','lock-in');}
  function rescueStart(){const r=currentRecord();r.rescueMode=true;save();render();toast('Rescue mode is ready. Small actions count.','info');}
  function closeDayModal(){const r=currentRecord();const incomplete=objectives(r).map((ok,i)=>ok?null:['Prayer','Build','Math','Body','Attention','Sleep'][i]).filter(Boolean);openModal('Close the day',`<div class="grid grid-2"><div class="mission-box"><div class="mission-label">Discipline Score</div><div class="mission-value">${scoreRecord(r)} / 100 · ${scoreName(scoreRecord(r))}</div></div><div class="mission-box"><div class="mission-label">Completed</div><div class="mission-value">${6-incomplete.length} / 6 objectives</div></div></div><p>${incomplete.length?`Still open: ${esc(incomplete.join(', '))}. The day remains editable after closing.`:'All six objectives are complete.'}</p><div class="scorecard"><div class="score-line"><span>Coding</span><span>${mins(r.coding.minutes)}</span></div><div class="score-line"><span>Math</span><span>${mins(r.math.minutes)} · ${r.math.questions||0} questions</span></div><div class="score-line"><span>Prayer</span><span>${Object.values(r.prayers).filter(Boolean).length}/5</span></div><div class="score-line"><span>Exercise</span><span>${(r.exercise.walking||0)+(r.exercise.workoutMinutes||0)} minutes</span></div></div><div class="field"><label>What is tomorrow's main mission?</label><input class="input" name="tomorrow" value="${esc(r.tomorrowMission||r.stream.tomorrow)}" maxlength="180" placeholder="A useful next action"></div><div class="field"><label>Evening reflection</label><textarea class="textarea" name="reflection" placeholder="What did you learn today?">${esc(r.journal.completed)}</textarea></div>`,'Close day','close-day');}
  function openDay(day){const cycle=ensureCycle(),date=dateForDay(day,cycle),r=record(date),score=scoreRecord(r);const title=`Day ${day} · ${fmtDate(date,{month:'long',day:'numeric'})}`;openModal(title,`<div class="grid grid-2"><div class="mission-box"><div class="mission-label">Discipline score</div><div class="mission-value">${score} / 100 · ${scoreName(score)}</div></div><div class="mission-box"><div class="mission-label">Day state</div><div class="mission-value">${r.rescueMode?'Rescued':r.closedDay?'Reviewed':date===todayISO()?'In progress':'Editable record'}</div></div></div><p>${esc(DAY_THEMES[day-1]||'Protocol day')}</p><div class="scorecard"><div class="score-line"><span>Prayer</span><span>${Object.values(r.prayers).filter(Boolean).length}/5</span></div><div class="score-line"><span>Coding</span><span>${mins(r.coding.minutes)}</span></div><div class="score-line"><span>Math</span><span>${mins(r.math.minutes)} · ${r.math.questions} questions</span></div><div class="score-line"><span>Movement</span><span>${(+r.exercise.walking||0)+(+r.exercise.workoutMinutes||0)}m</span></div><div class="score-line"><span>Protected attention</span><span>${r.dopamine.protected?'Yes':'Not marked'}</span></div><div class="score-line"><span>Sleep</span><span>${r.sleep.duration||0}h</span></div></div><div class="field"><label>Main mission</label><input class="input" data-history="mission" data-date="${date}" value="${esc(r.coding.mission||r.lockIn.mission)}"></div><div class="field"><label>Reflection</label><textarea class="textarea" data-history="reflection" data-date="${date}">${esc(r.journal.completed)}</textarea></div>${day===14&&date===todayISO()?`<p>Day 14 is complete. Review the cycle, export your report, then decide whether to start another.</p>`:''}`,null);}
  const openDayBase=openDay;
  openDay=function(day){openDayBase(day);const date=dateForDay(day),r=record(date),form=$('#modal-root form');if(!form)return;form.insertAdjacentHTML('afterbegin',`<div class="field"><label>Prayer check-ins</label><div class="field-row three">${PRAYERS.map(p=>`<label class="check-row"><input type="checkbox" data-history-prayer="${p}" data-date="${date}" ${r.prayers[p]?'checked':''}> ${p}</label>`).join('')}</div></div><div class="field-row three">${[['Coding minutes','codingMinutes',r.coding.minutes],['Math minutes','mathMinutes',r.math.minutes],['Questions','questions',r.math.questions],['Walk minutes','walking',r.exercise.walking],['Workout minutes','workoutMinutes',r.exercise.workoutMinutes],['Sleep hours','sleepDuration',r.sleep.duration]].map(([label,key,value])=>`<div class="field"><label>${label}</label><input class="input" type="number" min="0" step="${key==='sleepDuration'?'0.1':'1'}" data-history="${key}" data-date="${date}" value="${esc(value)}"></div>`).join('')}</div><label class="check-row" style="margin:8px 0 14px"><input type="checkbox" data-history="protected" data-date="${date}" ${r.dopamine.protected?'checked':''}> Protected first productive hours</label>`);};
  function editPrayerTimesModal(){openModal('Prayer times',`<p>Enter your local times. The app does not use an external prayer-time service.</p><div class="field-row">${PRAYERS.map(p=>`<div class="field"><label>${p}</label><input class="input" name="${p}" type="time" value="${esc(state.profile.prayerTimes[p])}"></div>`).join('')}</div>`,'Save times','prayer-times');}
  function quickAddModal(){openModal('Quick add',`<p>Choose a useful addition for today.</p><div class="grid grid-2"><button type="button" class="btn" data-action="add-task">Coding task</button><button type="button" class="btn" data-action="add-topic">Math topic</button><button type="button" class="btn" data-action="quick-journal">Journal note</button><button type="button" class="btn" data-action="workout">Workout</button><button type="button" class="btn" data-action="stream-note">Stream note</button><button type="button" class="btn" data-action="add-routine">Routine block</button></div>`,'', 'quick-add');}
  function commandPalette(){const commands=[['Start Coding Focus','start-coding'],['Start Math Focus','start-math'],['Mark Prayer','jump-prayers'],['Open Today','page:today'],['Open Analytics','page:analytics'],['Add Coding Task','add-task'],['Add Math Topic','add-topic'],['Rescue This Day','rescue'],['Export Data','export'],['Toggle Theme','toggle-theme']];const searchables=[];Object.values(state.dailyRecords).forEach(r=>{(r.coding.tasks||[]).forEach(t=>searchables.push({label:`Task · ${t.text}`,action:'open-day',day:protocolDay(r.date)}));});(state.profile.topics||[]).forEach(t=>searchables.push({label:`Math · ${t.name}`,action:'page:settings'}));Object.entries(state.dailyRecords).forEach(([date,r])=>{const text=r.journal?.completed||r.journal?.learned;if(text)searchables.push({label:`Journal · ${date} · ${text.slice(0,55)}`,action:'open-date',date});});const all=commands.map(([label,action])=>({label,action})).concat(searchables);openModal('Command palette',`<div class="field"><label class="sr-only" for="command-search">Search commands and local records</label><input class="input" id="command-search" placeholder="Search commands, tasks, topics, journal…" autocomplete="off"></div><div id="command-results" class="objective-list">${commandItems(all)}</div>`,'','command');$('#command-search')?.focus();$('#command-search').dataset.commands=JSON.stringify(all);}
  function commandItems(items){return items.slice(0,12).map((x,i)=>`<button type="button" class="objective-row" style="width:100%;background:transparent;color:var(--text);text-align:left;border:0" data-command-index="${i}"><span>${esc(x.label)}</span><span class="quiet">↵</span></button>`).join('')||'<div class="empty-state">No local matches.</div>';}
  function confirmNewCycle(){openModal('Start a new 14-day cycle',`<p>Your existing cycle and daily history stay saved. The new cycle starts today.</p><div class="mission-box"><div class="mission-label">New cycle start</div><div class="mission-value">${esc(fmtDate(todayISO()))}</div></div>`,'Start cycle','new-cycle');}
  function confirmReset(){openModal('Reset application',`<p>This permanently removes this browser's Rebuild OS data. Export a backup first if you need to keep it.</p><div class="field"><label>Type RESET to confirm</label><input class="input" name="confirmation" autocomplete="off" required></div>`,'Reset all data','reset');}

  // 10. Timer and record mutation
  const TIMER_DEFAULTS={Coding:120,Math:60,Workout:30,Custom:45};
  function setTimerMode(mode){const old=state.appState.timer;if(old?.active)return toast('Pause or stop the active session before changing modes.','warning');state.appState.timer={type:mode,target:(TIMER_DEFAULTS[mode]||45)*60,elapsed:0,active:false,startedAt:null,task:'',notes:''};save();setPage('focus');}
  function startTimer(){let t=state.appState.timer;if(!t)t=state.appState.timer={type:'Coding',target:7200,elapsed:0,active:false,task:'',notes:''};if(t.active)return;t.active=true;t.startedAt=Date.now();save();toast(`${t.type} focus started.`,'success');render();}
  function pauseTimer(){const t=state.appState.timer;if(!t?.active)return;t.elapsed=focusElapsed();t.active=false;t.startedAt=null;save();render();toast('Session paused. Timer state saved.','info');}
  function saveFocusSession(){const t=state.appState.timer;if(!t)return;const seconds=focusElapsed(),minutes=Math.max(1,Math.round(seconds/60));if(seconds>=20){const session={id:uid(),date:todayISO(),type:t.type,minutes,task:t.task||'',notes:t.notes||'',startedAt:t.startedAt?new Date(t.startedAt).toISOString():new Date().toISOString(),savedAt:new Date().toISOString()};state.focusSessions.push(session);const r=currentRecord();if(t.type==='Coding'){r.coding.minutes+=minutes;if(t.task&&!r.coding.mission)r.coding.mission=t.task;}else if(t.type==='Math'){r.math.minutes+=minutes;if(t.task)r.math.topic=t.task;const topic=(state.profile.topics||[]).find(x=>x.name.toLowerCase()===String(t.task||'').toLowerCase());if(topic){topic.minutes=(topic.minutes||0)+minutes;topic.lastStudied=todayISO();}}else if(t.type==='Workout'){r.exercise.workoutMinutes+=minutes;r.exercise.workout=true;}r.score=scoreRecord(r);toast(`${t.type} session saved · ${mins(minutes)}.`,'success');}else toast('Short session discarded. No focus time was added.','info');state.appState.timer={type:t.type,target:t.target,elapsed:0,active:false,startedAt:null,task:'',notes:''};save();render();}
  function resetTimer(){const t=state.appState.timer;if(t?.active)return toast('Pause or stop the timer before resetting.','warning');state.appState.timer={type:t?.type||'Coding',target:t?.target||7200,elapsed:0,active:false,startedAt:null,task:'',notes:''};save();render();}
  function updateTimerDisplay(){const countdown=$('[data-prayer-countdown]');if(countdown&&state.appState.page==='today')countdown.textContent=prayerCountdown(remainingPrayer());const t=state.appState.timer;if(!t?.active||state.appState.page!=='focus')return;const elapsed=focusElapsed(),remain=Math.max(0,t.target-elapsed),display=$('#timer-display'),bar=$('#timer-progress');if(display)display.textContent=durationLabel(remain);if(bar)bar.style.setProperty('--progress',`${Math.min(100,elapsed/Math.max(1,t.target)*100)}%`);if(remain<=0)saveFocusSession();}
  setInterval(updateTimerDisplay,1000);
  function recalcSleep(r){const s=r.sleep;if(!s.bedtime||!s.wakeTime){s.duration=0;return;}const [bh,bm]=s.bedtime.split(':').map(Number),[wh,wm]=s.wakeTime.split(':').map(Number);let end=wh*60+wm,start=bh*60+bm;if(end<=start)end+=1440;s.duration=Math.round(((end-start)/60)*10)/10;}
  function createExport(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`rebuild-os-backup-${todayISO()}.json`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Backup downloaded.','success');}
  function exportReport(){createExport();const cycle=ensureCycle(),dates=Array.from({length:14},(_,i)=>dateForDay(i+1,cycle)),records=dates.map(d=>state.dailyRecords[d]).filter(Boolean);const text=[`REBUILD OS · PROTOCOL REPORT`,`Cycle: ${fmtDate(cycle.startDate,{month:'long',day:'numeric',year:'numeric'})} to ${fmtDate(addDays(cycle.startDate,13),{month:'long',day:'numeric',year:'numeric'})}`,`Average score: ${records.length?Math.round(records.reduce((n,r)=>n+scoreRecord(r),0)/records.length):0}/100`,`Prayers completed: ${records.reduce((n,r)=>n+Object.values(r.prayers||{}).filter(Boolean).length,0)}`,`Coding time: ${mins(records.reduce((n,r)=>n+(+r.coding.minutes||0),0))}`,`Math time: ${mins(records.reduce((n,r)=>n+(+r.math.minutes||0),0))}`,`Questions solved: ${records.reduce((n,r)=>n+(+r.math.questions||0),0)}`,`Workouts: ${records.filter(r=>r.exercise.workout).length}`,`Rescued days: ${records.filter(r=>r.rescueMode).length}`,`Project: ${state.profile.projectName||'Not set'} · ${state.profile.projectStatus||'Planned'}`].join('\n');const blob=new Blob([text],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`rebuild-os-report-${todayISO()}.txt`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Cycle report downloaded as JSON and text.','success');}
  function createSnapshot(){try{const stamp=new Date().toISOString().replace(/[:.]/g,'-');localStorage.setItem(`${KEY}_snapshot_${stamp}`,JSON.stringify(state));toast('Local snapshot created.','success');}catch{toast('Could not create snapshot. Browser storage may be full.','error');}}
  function importFile(){ $('#import-file')?.click(); }
  function validateBackup(data){return !!data&&typeof data==='object'&&!Array.isArray(data)&&data.version===1&&data.profile&&typeof data.profile==='object'&&!Array.isArray(data.profile)&&data.settings&&typeof data.settings==='object'&&!Array.isArray(data.settings)&&data.dailyRecords&&typeof data.dailyRecords==='object'&&!Array.isArray(data.dailyRecords)&&Object.entries(data.dailyRecords).every(([date,r])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&r&&typeof r==='object'&&!Array.isArray(r))&&Array.isArray(data.cycles)&&Array.isArray(data.focusSessions);}
  async function importSelected(file){if(!file)return;try{const data=JSON.parse(await file.text());if(!validateBackup(data)){toast('That file is not a valid Rebuild OS v1 backup.','error');return;}createSnapshot();openModal('Replace current data?',`<p>The selected backup contains ${Object.keys(data.dailyRecords).length} daily records. A local snapshot of the current data was created first.</p><p>Importing replaces the active data in this browser.</p><input type="hidden" name="backup" value="${esc(JSON.stringify(data))}">`,'Import backup','import-confirm');window.__pendingImport=data;}catch{toast('The selected file is not valid JSON.','error');}}
  function dailySummary(){const r=currentRecord(),day=protocolDay();return `REBUILD OS — Day ${day}\n\nDiscipline Score: ${scoreRecord(r)}/100\n\nPrayer: ${Object.values(r.prayers).filter(Boolean).length}/5\nCoding: ${mins(r.coding.minutes)}\nMath: ${mins(r.math.minutes)}\nQuestions: ${r.math.questions||0}\nExercise: ${(r.exercise.walking||0)+(r.exercise.workoutMinutes||0)}m\nProtected Morning: ${r.dopamine.protected?'Yes':'No'}\nSleep: ${r.sleep.duration||0}h\n\nMain Mission:\n${r.coding.mission||r.lockIn.mission||'Not set'}\n\nTomorrow:\n${r.tomorrowMission||r.stream.tomorrow||'Not set'}`;}
  async function copySummary(){try{await navigator.clipboard.writeText(dailySummary());toast('Daily summary copied.','success');}catch{openModal('Daily summary',`<textarea class="textarea" readonly>${esc(dailySummary())}</textarea>`,'','summary');$('.textarea',$('#modal-root'))?.select();}}
  function completeTopicQuestion(){const topics=state.profile.topics||[];openModal('Log a math question',`<div class="field"><label>Topic</label><select class="select" name="topicId">${topics.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Result</label><select class="select" name="correct"><option value="true">Correct</option><option value="false">Incorrect</option></select></div>`,'Log question','question');}
  function workoutModal(){openModal('Log movement',`<div class="field-row"><div class="field"><label>Workout minutes</label><input class="input" name="minutes" type="number" min="0" value="${currentRecord().exercise.workoutMinutes||30}"></div><div class="field"><label>Walk minutes</label><input class="input" name="walking" type="number" min="0" value="${currentRecord().exercise.walking||0}"></div></div><div class="field-row"><div class="field"><label>Activity</label><select class="select" name="type">${['Walking','Gym','Home workout','Mixed'].map(x=>`<option ${currentRecord().exercise.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Steps (optional)</label><input class="input" name="steps" type="number" min="0" value="${esc(currentRecord().exercise.steps)}"></div></div><div class="field"><label>Notes</label><input class="input" name="notes" value="${esc(currentRecord().exercise.notes)}" placeholder="Short note"></div>`,'Log movement','workout');}
  function routineModal(){const r=currentRecord();openModal('Add routine block',`<div class="field"><label>Label</label><input class="input" name="label" required maxlength="80" placeholder="e.g. Coding block"></div><div class="field-row"><div class="field"><label>Start</label><input class="input" name="start" type="time" required value="09:00"></div><div class="field"><label>End</label><input class="input" name="end" type="time" required value="10:00"></div></div><div class="field"><label>Category</label><select class="select" name="category">${['routine','prayer','coding','math','body','stream','sleep'].map(x=>`<option>${x}</option>`).join('')}</select></div>`,'Add block','routine');}
  function editRoutineModal(){const r=currentRecord(),blocks=r.timeline?.length?r.timeline:DEFAULT_ROUTINE.map((b,i)=>({id:`default-${i}`,label:b[0],start:b[1],end:b[2],category:b[3]}));openModal('Customize timeline',`<div class="topic-list">${blocks.map(b=>`<div class="topic-item"><span class="small quiet">${esc(b.start)}</span><div><div class="topic-name">${esc(b.label)}</div><div class="topic-meta">${esc(b.end)} · ${esc(b.category)}</div></div><button type="button" class="btn sm" data-action="edit-routine-block" data-id="${esc(b.id)}">Edit</button><button type="button" class="task-remove" data-action="remove-routine" data-id="${esc(b.id)}">Remove</button></div>`).join('')}</div><p>New blocks are added on the Today screen.</p>`,'','edit-routine');}
  function routineBlockModal(id){const r=currentRecord();if(!r.timeline?.length)r.timeline=DEFAULT_ROUTINE.map((b,i)=>({id:`default-${i}`,label:b[0],start:b[1],end:b[2],category:b[3]}));const b=r.timeline.find(x=>x.id===id);if(!b)return;openModal('Edit routine block',`<input type="hidden" name="id" value="${esc(b.id)}"><div class="field"><label>Label</label><input class="input" name="label" required value="${esc(b.label)}"></div><div class="field-row"><div class="field"><label>Start</label><input class="input" name="start" type="time" required value="${esc(b.start)}"></div><div class="field"><label>End</label><input class="input" name="end" type="time" required value="${esc(b.end)}"></div></div><div class="field"><label>Category</label><select class="select" name="category">${['routine','prayer','coding','math','body','stream','sleep'].map(x=>`<option ${b.category===x?'selected':''}>${x}</option>`).join('')}</select></div>`,'Save block','routine-edit');}

  // 11. Event handlers
  function handleFormSubmit(e){const form=e.target.closest('[data-modal-form]');if(!form)return;e.preventDefault();const kind=form.dataset.modalForm,fd=new FormData(form),r=currentRecord();
    if(kind==='task'){const text=String(fd.get('text')||'').trim();if(text){r.coding.tasks.push({id:uid(),text,done:false,createdAt:new Date().toISOString()});save();closeModal();render();toast('Task added.','success');}}
    else if(kind==='task-edit'){const task=r.coding.tasks.find(t=>t.id===fd.get('id')),text=String(fd.get('text')||'').trim();if(task&&text){task.text=text;save();closeModal();render();toast('Task updated.','success');}}
    else if(kind==='topic'){const name=String(fd.get('name')||'').trim();if(name){state.profile.topics.push({id:uid(),name,notes:String(fd.get('notes')||''),done:false,confidence:1,questions:0,correct:0,incorrect:0,minutes:0,lastStudied:''});save();closeModal();render();toast('Math topic added.','success');}}
    else if(kind==='quick-log'){const n=Math.max(0,Number(fd.get('minutes'))||0),type=form.dataset.kind||'coding';if(type==='coding')r.coding.minutes+=n;else if(type==='math'){r.math.minutes+=n;r.math.questions+=Math.max(0,Number(fd.get('questions'))||0);if(fd.get('note'))r.math.notes=String(fd.get('note'));}else r.exercise.walking+=n;save();closeModal();render();toast(`${mins(n)} added to ${type}.`,'success');}
    else if(kind==='lock-in'){r.lockIn={mission:String(fd.get('mission')||''),topic:String(fd.get('topic')||''),workout:String(fd.get('workout')||''),distraction:String(fd.get('distraction')||''),locked:true};r.coding.mission=r.lockIn.mission;r.math.topic=r.lockIn.topic;save();closeModal();render();toast('Day locked.','success');}
    else if(kind==='close-day'){r.closedDay=true;r.tomorrowMission=String(fd.get('tomorrow')||'').trim();if(r.tomorrowMission){const tomorrow=record(addDays(todayISO(),1));tomorrow.coding.mission=r.tomorrowMission;}if(fd.get('reflection'))r.journal.completed=String(fd.get('reflection'));r.score=scoreRecord(r);save();closeModal();render();toast('Day reviewed. Your record stays editable.','success');}
    else if(kind==='prayer-times'){for(const p of PRAYERS)state.profile.prayerTimes[p]=String(fd.get(p)||state.profile.prayerTimes[p]);save();closeModal();render();toast('Prayer times updated.','success');}
    else if(kind==='new-cycle'){const cycle={id:uid(),startDate:todayISO(),createdAt:new Date().toISOString(),label:'14-Day Rebuild Protocol'};state.cycles.push(cycle);state.currentCycleId=cycle.id;state.profile.startDate=cycle.startDate;save();closeModal();render();toast('New 14-day cycle started. Previous history is preserved.','success');}
    else if(kind==='reset'){if(fd.get('confirmation')!=='RESET'){toast('Type RESET exactly to confirm.','warning');return;}localStorage.removeItem(KEY);location.reload();}
    else if(kind==='import-confirm'){if(!window.__pendingImport)return;state=window.__pendingImport;ensureShape();state.appState.setupComplete=true;save();delete window.__pendingImport;closeModal();render();toast('Backup imported.','success');}
    else if(kind==='question'){const topic=(state.profile.topics||[]).find(t=>t.id===fd.get('topicId'));if(topic){const correct=fd.get('correct')==='true';topic.questions=(topic.questions||0)+1;topic[correct?'correct':'incorrect']=(topic[correct?'correct':'incorrect']||0)+1;topic.lastStudied=todayISO();r.math.questions++;r.math[correct?'correct':'incorrect']++;save();closeModal();render();toast('Question recorded.','success');}}
    else if(kind==='workout'){const minsN=Math.max(0,Number(fd.get('minutes'))||0),walk=Math.max(0,Number(fd.get('walking'))||0);r.exercise.workoutMinutes=minsN;r.exercise.walking=walk;r.exercise.workout=minsN>0;r.exercise.type=String(fd.get('type')||'Walking');r.exercise.steps=String(fd.get('steps')||'');r.exercise.notes=String(fd.get('notes')||'');save();closeModal();render();toast('Movement logged.','success');}
    else if(kind==='routine'){if(!r.timeline?.length)r.timeline=DEFAULT_ROUTINE.map((b,i)=>({id:`default-${i}`,label:b[0],start:b[1],end:b[2],category:b[3]}));r.timeline.push({id:uid(),label:String(fd.get('label')||'Block'),start:String(fd.get('start')),end:String(fd.get('end')),category:String(fd.get('category')||'routine')});save();closeModal();render();toast('Routine block added.','success');}
    else if(kind==='routine-edit'){const block=r.timeline.find(b=>b.id===fd.get('id'));if(block){block.label=String(fd.get('label'));block.start=String(fd.get('start'));block.end=String(fd.get('end'));block.category=String(fd.get('category'));save();closeModal();render();toast('Routine block updated.','success');}}
  }
  function handleAction(action,el){const r=currentRecord(),id=el?.dataset.id;
    switch(action){
      case 'close-modal':closeModal();break;
      case 'command':commandPalette();break;
      case 'quick-add':quickAddModal();break;
      case 'add-task':closeModal();addTaskModal();break;
      case 'edit-task':editTaskModal(id);break;
      case 'add-topic':closeModal();addTopicModal();break;
      case 'quick-log':quickLogModal(el.dataset.kind||'coding');const f=$('[data-modal-form="quick-log"]');if(f)f.dataset.kind=el.dataset.kind||'coding';break;
      case 'lock-in':lockInModal();break;
      case 'close-day':closeDayModal();break;
      case 'rescue':rescueStart();break;
      case 'exit-rescue':r.rescueMode=false;save();render();toast('Rescue mode closed.','info');break;
      case 'start-coding':state.appState.page='focus';if(!state.appState.timer||!state.appState.timer.active)state.appState.timer={type:'Coding',target:state.settings.codingTarget*60,elapsed:0,active:false,startedAt:null,task:r.coding.mission||r.lockIn.mission||'',notes:''};save();render();startTimer();break;
      case 'start-math':state.appState.page='focus';if(!state.appState.timer||!state.appState.timer.active)state.appState.timer={type:'Math',target:state.settings.mathTarget*60,elapsed:0,active:false,startedAt:null,task:r.math.topic||r.lockIn.topic||'',notes:''};save();render();startTimer();break;
      case 'start-workout':state.appState.page='focus';state.appState.timer={type:'Workout',target:state.settings.exerciseTarget*60,elapsed:0,active:false,startedAt:null,task:r.exercise.type,notes:''};save();render();startTimer();break;
      case 'timer-start':startTimer();break;
      case 'timer-pause':pauseTimer();break;
      case 'timer-stop':saveFocusSession();break;
      case 'timer-reset':resetTimer();break;
      case 'timer-mode':setTimerMode(el.dataset.mode);break;
      case 'add-routine':closeModal();routineModal();break;
      case 'edit-routine':editRoutineModal();break;
      case 'edit-routine-block':routineBlockModal(id);break;
      case 'remove-routine':if(!r.timeline?.length)r.timeline=DEFAULT_ROUTINE.map((b,i)=>({id:`default-${i}`,label:b[0],start:b[1],end:b[2],category:b[3]}));r.timeline=r.timeline.filter(b=>b.id!==id);save();editRoutineModal();break;
      case 'log-walk':quickLogModal('movement');break;
      case 'workout':workoutModal();break;
      case 'question':completeTopicQuestion();break;
      case 'edit-prayer-times':editPrayerTimesModal();break;
      case 'open-day':openDay(Number(el.dataset.day));break;
      case 'open-date':{const d=el.dataset.date;openModal(`Journal · ${fmtDate(d)}`,`<p>${esc(state.dailyRecords[d]?.journal?.completed||state.dailyRecords[d]?.journal?.learned||'No journal entry saved.')}</p><div class="small muted">${esc(d)}</div>`,null);break;}
      case 'new-cycle':confirmNewCycle();break;
      case 'focus-mode':if(state.appState.page==='focus'&&state.appState.focusMode){state.appState.focusMode=false;}else{state.appState.page='focus';state.appState.focusMode=true;if(!state.appState.timer)state.appState.timer={type:'Coding',target:state.settings.codingTarget*60,elapsed:0,active:false,startedAt:null,task:r.coding.mission||'',notes:''};}save();render();break;
      case 'jump-prayers':setPage('today');setTimeout(()=>$('#prayers')?.scrollIntoView({behavior:'smooth',block:'center'}),40);break;
      case 'protect':r.dopamine.protected=true;save();render();toast('First productive hours protected.','success');break;
      case 'go-journal':setPage('journal');break;
      case 'copy-summary':copySummary();break;
      case 'export':createExport();break;
      case 'export-report':exportReport();break;
      case 'import':importFile();break;
      case 'snapshot':createSnapshot();break;
      case 'reset':confirmReset();break;
      case 'toggle-theme':state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();render();toast(`${state.settings.theme==='dark'?'Dark':'Light'} theme enabled.`,'info');break;
      case 'ship-project':{const features=state.profile.features||[];if(features.length===3&&features.every(f=>f.done)&&state.profile.deploymentUrl){state.profile.projectStatus='Shipped';save();render();toast('Project marked shipped. Build proof captured.','success');}else toast('Complete all three core features and add a deployment URL first.','warning');break;}
      case 'add-routine':routineModal();break;
      case 'stream-note':setPage('today');setTimeout(()=>$('#stream')?.scrollIntoView({behavior:'smooth',block:'center'}),50);break;
      case 'quick-journal':closeModal();openModal('Quick journal note',`<div class="field"><label>Note</label><textarea class="textarea" name="note" required placeholder="Write one useful sentence"></textarea></div>`,'Save note','journal-note');break;
      case 'rating':r.journal[el.dataset.key]=Number(el.dataset.value);save();render();break;
      case 'topic-rating':{const t=(state.profile.topics||[]).find(x=>x.id===id);if(t){t.confidence=Number(el.dataset.value);save();render();}break;}
      case 'delete-task':r.coding.tasks=r.coding.tasks.filter(t=>t.id!==id);save();render();toast('Task removed.','info');break;
      case 'reorder-task':{const i=r.coding.tasks.findIndex(t=>t.id===id),j=i+(el.dataset.direction==='up'?-1:1);if(i>=0&&j>=0&&j<r.coding.tasks.length){[r.coding.tasks[i],r.coding.tasks[j]]=[r.coding.tasks[j],r.coding.tasks[i]];save();render();}break;}
      case 'delete-topic':state.profile.topics=state.profile.topics.filter(t=>t.id!==id);save();render();toast('Topic removed.','info');break;
      case 'onboard-back':onboardStep=Math.max(0,onboardStep-1);render();break;
      case 'onboard-next':if(onboardStep===0&&!state.profile.name?.trim()){toast('Add your name to continue.','warning');return;}if(onboardStep<5)onboardStep++;render();break;
      case 'finish-onboarding':state.appState.setupComplete=true;if(!state.profile.topics)state.profile.topics=[];if(!state.profile.features)state.profile.features=['','',''].map(text=>({text,done:false}));ensureCycle();save();$('#modal-root').innerHTML='';render();toast('Your Rebuild OS is ready.','success');break;
    }
  }
  function handleClick(e){const nav=e.target.closest('[data-page]');if(nav){setPage(nav.dataset.page);return;}const scroll=e.target.closest('[data-scroll]');if(scroll){document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});$$('.settings-tab').forEach(x=>x.classList.toggle('active',x===scroll));return;}const cmd=e.target.closest('[data-command-index]');if(cmd){const list=JSON.parse($('#command-search')?.dataset.commands||'[]'),item=list[Number(cmd.dataset.commandIndex)];if(item){closeModal();if(item.action.startsWith('page:'))setPage(item.action.slice(5));else if(item.action==='open-day')openDay(item.day);else if(item.action==='open-date')handleAction('open-date',{dataset:{date:item.date}});else handleAction(item.action,null);}return;}const actionEl=e.target.closest('[data-action]');if(actionEl){handleAction(actionEl.dataset.action,actionEl);return;}if(e.target.matches('[data-modal-backdrop]'))closeModal();}

  function handleInput(e){const t=e.target,r=currentRecord();
    if(t.dataset.profile){const key=t.dataset.profile;state.profile[key]=t.type==='number'?(Number(t.value)||0):t.value;if(key==='startDate'&&state.currentCycleId){const c=state.cycles.find(x=>x.id===state.currentCycleId);if(c)c.startDate=t.value;}save();if(key==='name'){$('.profile-name')&&($('.profile-name').textContent=t.value||'Your profile');$('.greeting')&&($('.greeting').textContent=`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${t.value||'there'}.`);}return;}
    if(t.dataset.setting){const key=t.dataset.setting;state.settings[key]=t.type==='checkbox'?t.checked:key==='codingTarget'||key==='mathTarget'||key==='exerciseTarget'?Number(t.value):t.value;save();if(key==='theme'||key==='accent'){document.documentElement.dataset.theme=state.settings.theme;document.documentElement.dataset.accent=state.settings.accent;}return;}
    if(t.dataset.onboard==='topics'){state.profile.topics=t.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(name=>({id:uid(),name,notes:'',done:false,confidence:1,questions:0,correct:0,incorrect:0,minutes:0,lastStudied:''}));save();return;}
    if(t.dataset.onboard){const key=t.dataset.onboard;state.profile[key]=key==='sleepTarget'?(Number(t.value)||7.5):t.value;if(key==='startDate'&&state.currentCycleId){const cycle=state.cycles.find(c=>c.id===state.currentCycleId);if(cycle)cycle.startDate=t.value;}save();return;}
    if(t.dataset.onboardFeature!==undefined){const i=Number(t.dataset.onboardFeature);state.profile.features=state.profile.features||['','',''].map(text=>({text,done:false}));state.profile.features[i]={...(typeof state.profile.features[i]==='object'?state.profile.features[i]:{done:false}),text:t.value};save();return;}
    if(t.dataset.onboardPrayer){state.profile.prayerTimes[t.dataset.onboardPrayer]=t.value;save();return;}
    if(t.dataset.prayerTime){state.profile.prayerTimes[t.dataset.prayerTime]=t.value;save();return;}
    if(t.dataset.featureName!==undefined){const i=Number(t.dataset.featureName);state.profile.features[i]={...(state.profile.features[i]||{done:false}),text:t.value};save();return;}
    if(t.dataset.timerField){const timer=state.appState.timer||{};if(t.dataset.timerField==='target')timer.target=Math.max(60,(Number(t.value)||1)*60);else timer[t.dataset.timerField]=t.value;state.appState.timer=timer;save();return;}
    if(t.dataset.journal){r.journal[t.dataset.journal]=t.value;save();const status=$('#journal-saved');if(status){status.textContent='Saved';status.style.opacity=1;setTimeout(()=>{if(status.isConnected)status.style.opacity=.55;},1200);}return;}
    if(t.dataset.stream){r.stream[t.dataset.stream]=t.type==='checkbox'?t.checked:t.value;save();if(t.dataset.stream==='tomorrow'&&t.value){const next=record(addDays(todayISO(),1));next.coding.mission=t.value;}return;}
    if(t.dataset.sleep){r.sleep[t.dataset.sleep]=t.value;recalcSleep(r);save();return;}
    if(t.dataset.history){if(t.type==='checkbox')return;const rec=record(t.dataset.date),key=t.dataset.history;if(key==='mission')rec.coding.mission=t.value;else if(key==='reflection')rec.journal.completed=t.value;else if(key==='codingMinutes')rec.coding.minutes=Math.max(0,Number(t.value)||0);else if(key==='mathMinutes')rec.math.minutes=Math.max(0,Number(t.value)||0);else if(key==='questions')rec.math.questions=Math.max(0,Number(t.value)||0);else if(key==='walking')rec.exercise.walking=Math.max(0,Number(t.value)||0);else if(key==='workoutMinutes'){rec.exercise.workoutMinutes=Math.max(0,Number(t.value)||0);rec.exercise.workout=rec.exercise.workoutMinutes>0;}else if(key==='sleepDuration')rec.sleep.duration=Math.max(0,Number(t.value)||0);rec.score=scoreRecord(rec);save();return;}
    if(t.dataset.import){return;}
    if(t.id==='command-search'){const list=JSON.parse(t.dataset.commands||'[]'),q=t.value.trim().toLowerCase();const filtered=q?list.filter(x=>x.label.toLowerCase().includes(q)):list;$('#command-results').innerHTML=commandItems(filtered);$('#command-search').dataset.commands=JSON.stringify(filtered);return;}
  }
  function handleChange(e){const t=e.target,r=currentRecord();
    if(t.dataset.historyPrayer){const date=t.dataset.date,rec=record(date),p=t.dataset.historyPrayer;rec.prayers[p]=t.checked;rec.prayerCompletedAt=rec.prayerCompletedAt||{};rec.prayerCompletedAt[p]=t.checked?new Date().toISOString():null;rec.score=scoreRecord(rec);save();return;}
    if(t.dataset.history==='protected'){const rec=record(t.dataset.date);rec.dopamine.protected=t.checked;rec.score=scoreRecord(rec);save();return;}
    if(t.dataset.sleep){r.sleep[t.dataset.sleep]=t.value;recalcSleep(r);save();render();return;}
    if(t.dataset.taskCheck){const task=r.coding.tasks.find(x=>x.id===t.dataset.taskCheck);if(task){task.done=t.checked;task.completedAt=t.checked?new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'';save();render();if(t.checked)toast('Task completed.','success');}return;}
    if(t.dataset.prayer){const p=t.dataset.prayer;r.prayers[p]=t.checked;r.prayerCompletedAt=r.prayerCompletedAt||{};r.prayerCompletedAt[p]=t.checked?new Date().toISOString():null;save();render();toast(`${p} ${t.checked?'marked complete':'reopened'}.`,t.checked?'success':'info');return;}
    if(t.dataset.dopamine){r.dopamine[t.dataset.dopamine]=t.checked;save();render();return;}
    if(t.dataset.rescue){r.rescue[t.dataset.rescue]=t.checked;r.rescueMode=true;const complete=Object.values(r.rescue).every(Boolean);save();render();if(complete)toast('Zero avoided. Day rescued.','success');return;}
    if(t.dataset.routineCheck){r.routine[t.dataset.routineCheck]=t.checked;save();render();return;}
    if(t.dataset.shutdown!==undefined){r.shutdown=r.shutdown||{};r.shutdown[t.dataset.shutdown]=t.checked;save();return;}
    if(t.dataset.feature!==undefined){const f=state.profile.features[Number(t.dataset.feature)];if(f){f.done=t.checked;save();render();if(state.profile.features.every(x=>x.done)&&state.profile.deploymentUrl)toast('All core features are done. The project can be marked shipped.','success');}return;}
    if(t.dataset.topicDone){const topic=state.profile.topics.find(x=>x.id===t.dataset.topicDone);if(topic){topic.done=t.checked;save();render();}return;}
    if(t.id==='import-file'&&t.files?.[0]){importSelected(t.files[0]);t.value='';return;}
  }
  function handleSubmit(e){const form=e.target.closest('[data-modal-form]');if(!form)return;const kind=form.dataset.modalForm;
    if(kind==='command'){e.preventDefault();const first=$('[data-command-index]');first?.click();return;}
    if(kind==='journal-note'){e.preventDefault();const r=currentRecord(),note=String(new FormData(form).get('note')||'').trim();if(note){r.journal.learned=[r.journal.learned,note].filter(Boolean).join('\n');save();closeModal();render();toast('Journal note saved.','success');}return;}
    handleFormSubmit(e);
  }
  function handleKey(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandPalette();return;}if(e.key==='Escape'&&$('#modal-root .modal-backdrop')){closeModal();return;}if(e.code==='Space'&&state.appState.page==='focus'&&!e.target.matches('input,textarea,select,button')){e.preventDefault();state.appState.timer?.active?pauseTimer():startTimer();return;}if(e.key==='Tab'&&$('#modal-root .modal')){const dialog=$('#modal-root .modal'),items=$$('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex="0"]',dialog).filter(x=>x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
  function startApp(){document.addEventListener('click',handleClick);document.addEventListener('submit',handleSubmit);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);document.addEventListener('keydown',handleKey);if(!state.profile.topics)state.profile.topics=[];if(!state.profile.features)state.profile.features=['','',''].map(text=>({text,done:false}));render();if(!state.profile.name&&!state.appState.setupComplete){onboardStep=0;onboarding();}}
  startApp();
})();
